/**
 * Validation module for kspec files.
 *
 * Provides schema validation, reference validation, and orphan detection.
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import {
  AgentSchema,
  ConventionSchema,
  ManifestSchema,
  MetaManifestSchema,
  ObservationSchema,
  SpecItemSchema,
  TaskSchema,
  TasksFileSchema,
  UlidSchema,
  WorkflowSchema,
} from "../schema/index.js";
import { findMetaManifest, loadMetaContext } from "./meta.js";
import { loadPlans } from "./plans.js";
import {
  ReferenceIndex,
  type RefValidationError,
  type RefValidationWarning,
  validateRefs,
} from "./refs.js";
import { TraitIndex } from "./traits.js";
import type { KspecContext, LoadedSpecItem, LoadedTask } from "./yaml.js";
import {
  expandIncludePattern,
  extractItemsFromRaw,
  findTaskFiles,
  loadSpecFile,
  readYamlFile,
} from "./yaml.js";

// ============================================================
// TYPES
// ============================================================

/**
 * Schema validation error
 */
export interface SchemaValidationError {
  file: string;
  path?: string;
  message: string;
  details?: unknown;
}

/**
 * Orphan item (not referenced by anything)
 */
export interface OrphanItem {
  ulid: string;
  title: string;
  type: string;
  file?: string;
}

/**
 * Completeness warning types
 */
export type CompletenessWarningType =
  | "missing_acceptance_criteria"
  | "missing_description"
  | "status_inconsistency"
  | "missing_test_coverage"
  | "automation_eligible_no_spec";

/**
 * Trait cycle error
 */
export interface TraitCycleError {
  traitRef: string;
  traitTitle: string;
  cycle: string[];
  message: string;
}

/**
 * Completeness warning
 */
export interface CompletenessWarning {
  type: CompletenessWarningType;
  itemRef: string;
  itemTitle: string;
  message: string;
  details?: string;
}

/**
 * Complete validation result
 */
export interface ValidationResult {
  valid: boolean;
  schemaErrors: SchemaValidationError[];
  refErrors: RefValidationError[];
  refWarnings: RefValidationWarning[];
  orphans: OrphanItem[];
  completenessWarnings: CompletenessWarning[];
  traitCycleErrors: TraitCycleError[];
  stats: {
    filesChecked: number;
    itemsChecked: number;
    tasksChecked: number;
  };
  metaStats?: {
    agents: number;
    workflows: number;
    conventions: number;
    observations: number;
  };
}

/**
 * Validation options
 */
export interface ValidateOptions {
  /** Check schema conformance */
  schema?: boolean;
  /** Check reference resolution */
  refs?: boolean;
  /** Find orphaned items */
  orphans?: boolean;
  /** Check spec completeness (missing AC, descriptions, status inconsistencies) */
  completeness?: boolean;
}

// ============================================================
// SCHEMA VALIDATION
// ============================================================

/**
 * Validate a manifest file against schema
 */
async function validateManifestFile(
  filePath: string,
): Promise<SchemaValidationError[]> {
  const errors: SchemaValidationError[] = [];

  try {
    const raw = await readYamlFile<unknown>(filePath);
    const result = ManifestSchema.safeParse(raw);

    if (!result.success) {
      for (const issue of result.error.issues) {
        errors.push({
          file: filePath,
          path: issue.path.join("."),
          message: issue.message,
          details: issue,
        });
      }
    }
  } catch (err) {
    errors.push({
      file: filePath,
      message: `Failed to parse YAML: ${err instanceof Error ? err.message : String(err)}`,
    });
  }

  return errors;
}

/**
 * Validate a tasks file against schema
 */
async function validateTasksFile(
  filePath: string,
): Promise<SchemaValidationError[]> {
  const errors: SchemaValidationError[] = [];

  try {
    const raw = await readYamlFile<unknown>(filePath);

    // Handle both formats: { tasks: [...] } and plain array
    let taskList: unknown[];

    if (Array.isArray(raw)) {
      taskList = raw;
    } else if (raw && typeof raw === "object" && "tasks" in raw) {
      // Try full TasksFile schema first
      const fileResult = TasksFileSchema.safeParse(raw);
      if (!fileResult.success) {
        // If TasksFile fails, just validate individual tasks
        taskList = (raw as { tasks: unknown[] }).tasks || [];
      } else {
        // File schema passed, validate individual tasks for detailed errors
        taskList = fileResult.data.tasks;
      }
    } else {
      errors.push({
        file: filePath,
        message:
          "Invalid tasks file format: expected array or { tasks: [...] }",
      });
      return errors;
    }

    // Validate each task
    for (let i = 0; i < taskList.length; i++) {
      const task = taskList[i];
      const result = TaskSchema.safeParse(task);

      if (!result.success) {
        for (const issue of result.error.issues) {
          errors.push({
            file: filePath,
            path: `tasks[${i}].${issue.path.join(".")}`,
            message: issue.message,
            details: issue,
          });
        }
      }
    }
  } catch (err) {
    errors.push({
      file: filePath,
      message: `Failed to parse YAML: ${err instanceof Error ? err.message : String(err)}`,
    });
  }

  return errors;
}

/**
 * Validate a spec module file against schema
 */
async function validateSpecFile(
  filePath: string,
): Promise<SchemaValidationError[]> {
  const errors: SchemaValidationError[] = [];

  try {
    const raw = await readYamlFile<unknown>(filePath);

    // Recursively validate spec items
    validateSpecItemRecursive(raw, filePath, "", errors);
  } catch (err) {
    errors.push({
      file: filePath,
      message: `Failed to parse YAML: ${err instanceof Error ? err.message : String(err)}`,
    });
  }

  return errors;
}

/**
 * Validate meta manifest file with strict ULID validation
 * AC-meta-manifest-3: Invalid schema exits with code 1 and shows field path + expected type
 */
async function validateMetaManifestFile(
  filePath: string,
): Promise<SchemaValidationError[]> {
  const errors: SchemaValidationError[] = [];

  try {
    const raw = await readYamlFile<unknown>(filePath);

    // Validate overall manifest structure
    const manifestResult = MetaManifestSchema.safeParse(raw);
    if (!manifestResult.success) {
      for (const issue of manifestResult.error.issues) {
        errors.push({
          file: filePath,
          path: issue.path.join("."),
          message: issue.message,
          details: issue,
        });
      }
      return errors;
    }

    // Validate each agent with strict ULID validation
    if (
      raw &&
      typeof raw === "object" &&
      "agents" in raw &&
      Array.isArray((raw as Record<string, unknown>).agents)
    ) {
      const agents = (raw as Record<string, unknown>).agents as unknown[];
      for (let i = 0; i < agents.length; i++) {
        const agent = agents[i];
        const agentResult = AgentSchema.safeParse(agent);
        if (!agentResult.success) {
          for (const issue of agentResult.error.issues) {
            errors.push({
              file: filePath,
              path: `agents[${i}].${issue.path.join(".")}`,
              message: issue.message,
              details: issue,
            });
          }
        }

        // Strict ULID validation
        if (agent && typeof agent === "object" && "_ulid" in agent) {
          const ulidResult = UlidSchema.safeParse(
            (agent as Record<string, unknown>)._ulid,
          );
          if (!ulidResult.success) {
            errors.push({
              file: filePath,
              path: `agents[${i}]._ulid`,
              message: "Invalid ULID format (expected 26 characters)",
            });
          }
        }
      }
    }

    // Validate each workflow with strict ULID validation
    if (
      raw &&
      typeof raw === "object" &&
      "workflows" in raw &&
      Array.isArray((raw as Record<string, unknown>).workflows)
    ) {
      const workflows = (raw as Record<string, unknown>).workflows as unknown[];
      for (let i = 0; i < workflows.length; i++) {
        const workflow = workflows[i];
        const workflowResult = WorkflowSchema.safeParse(workflow);
        if (!workflowResult.success) {
          for (const issue of workflowResult.error.issues) {
            errors.push({
              file: filePath,
              path: `workflows[${i}].${issue.path.join(".")}`,
              message: issue.message,
              details: issue,
            });
          }
        }

        // Strict ULID validation
        if (workflow && typeof workflow === "object" && "_ulid" in workflow) {
          const ulidResult = UlidSchema.safeParse(
            (workflow as Record<string, unknown>)._ulid,
          );
          if (!ulidResult.success) {
            errors.push({
              file: filePath,
              path: `workflows[${i}]._ulid`,
              message: "Invalid ULID format (expected 26 characters)",
            });
          }
        }
      }
    }

    // Validate each convention with strict ULID validation
    if (
      raw &&
      typeof raw === "object" &&
      "conventions" in raw &&
      Array.isArray((raw as Record<string, unknown>).conventions)
    ) {
      const conventions = (raw as Record<string, unknown>)
        .conventions as unknown[];
      for (let i = 0; i < conventions.length; i++) {
        const convention = conventions[i];
        const conventionResult = ConventionSchema.safeParse(convention);
        if (!conventionResult.success) {
          for (const issue of conventionResult.error.issues) {
            errors.push({
              file: filePath,
              path: `conventions[${i}].${issue.path.join(".")}`,
              message: issue.message,
              details: issue,
            });
          }
        }

        // Strict ULID validation
        if (
          convention &&
          typeof convention === "object" &&
          "_ulid" in convention
        ) {
          const ulidResult = UlidSchema.safeParse(
            (convention as Record<string, unknown>)._ulid,
          );
          if (!ulidResult.success) {
            errors.push({
              file: filePath,
              path: `conventions[${i}]._ulid`,
              message: "Invalid ULID format (expected 26 characters)",
            });
          }
        }
      }
    }

    // Validate each observation with strict ULID validation
    if (
      raw &&
      typeof raw === "object" &&
      "observations" in raw &&
      Array.isArray((raw as Record<string, unknown>).observations)
    ) {
      const observations = (raw as Record<string, unknown>)
        .observations as unknown[];
      for (let i = 0; i < observations.length; i++) {
        const observation = observations[i];
        const observationResult = ObservationSchema.safeParse(observation);
        if (!observationResult.success) {
          for (const issue of observationResult.error.issues) {
            errors.push({
              file: filePath,
              path: `observations[${i}].${issue.path.join(".")}`,
              message: issue.message,
              details: issue,
            });
          }
        }

        // Strict ULID validation
        if (
          observation &&
          typeof observation === "object" &&
          "_ulid" in observation
        ) {
          const ulidResult = UlidSchema.safeParse(
            (observation as Record<string, unknown>)._ulid,
          );
          if (!ulidResult.success) {
            errors.push({
              file: filePath,
              path: `observations[${i}]._ulid`,
              message: "Invalid ULID format (expected 26 characters)",
            });
          }
        }
      }
    }
  } catch (err) {
    errors.push({
      file: filePath,
      message: `Failed to parse YAML: ${err instanceof Error ? err.message : String(err)}`,
    });
  }

  return errors;
}

/**
 * Recursively validate spec items in a structure
 */
function validateSpecItemRecursive(
  raw: unknown,
  file: string,
  pathPrefix: string,
  errors: SchemaValidationError[],
): void {
  if (!raw || typeof raw !== "object") return;

  // Check if this is a spec item (has _ulid)
  if ("_ulid" in raw) {
    const result = SpecItemSchema.safeParse(raw);
    if (!result.success) {
      for (const issue of result.error.issues) {
        errors.push({
          file,
          path: pathPrefix
            ? `${pathPrefix}.${issue.path.join(".")}`
            : issue.path.join("."),
          message: issue.message,
          details: issue,
        });
      }
    }
  }

  // Recurse into nested structures
  const nestedFields = [
    "modules",
    "features",
    "requirements",
    "constraints",
    "decisions",
    "items",
  ];
  const obj = raw as Record<string, unknown>;

  for (const field of nestedFields) {
    if (field in obj && Array.isArray(obj[field])) {
      const arr = obj[field] as unknown[];
      for (let i = 0; i < arr.length; i++) {
        const newPath = pathPrefix
          ? `${pathPrefix}.${field}[${i}]`
          : `${field}[${i}]`;
        validateSpecItemRecursive(arr[i], file, newPath, errors);
      }
    }
  }
}

// ============================================================
// ORPHAN DETECTION
// ============================================================

/**
 * Find items that are not referenced by any other item
 */
function findOrphans(
  tasks: LoadedTask[],
  items: LoadedSpecItem[],
  index: ReferenceIndex,
): OrphanItem[] {
  const orphans: OrphanItem[] = [];

  // Build set of all referenced ULIDs
  const referenced = new Set<string>();

  const allItems = [...tasks, ...items];

  // Fields that contain references
  const refFields = [
    "depends_on",
    "blocked_by",
    "implements",
    "relates_to",
    "tests",
    "supersedes",
    "spec_ref",
    "context",
  ];

  for (const item of allItems) {
    const obj = item as unknown as Record<string, unknown>;

    for (const field of refFields) {
      const value = obj[field];

      if (typeof value === "string" && value.startsWith("@")) {
        const resolved = index.resolve(value);
        if (resolved.ok) {
          referenced.add(resolved.ulid);
        }
      } else if (Array.isArray(value)) {
        for (const v of value) {
          if (typeof v === "string" && v.startsWith("@")) {
            const resolved = index.resolve(v);
            if (resolved.ok) {
              referenced.add(resolved.ulid);
            }
          }
        }
      }
    }
  }

  // Find items not in the referenced set
  // Skip entry point types: modules are spec entry points, tasks are work items
  const entryPointTypes = ["module", "task", "epic", "bug", "spike", "infra"];

  for (const item of items) {
    // Only check spec items, not tasks
    if (!referenced.has(item._ulid)) {
      // Skip entry point types
      if (entryPointTypes.includes(item.type || "")) continue;

      // Skip nested items - they're implicitly referenced by their parent
      // _path indicates nesting (e.g., "features[0].requirements[2]")
      if (item._path) continue;

      orphans.push({
        ulid: item._ulid,
        title: item.title,
        type: item.type || "unknown",
        file: item._sourceFile,
      });
    }
  }

  return orphans;
}

// ============================================================
// TRAIT CYCLE DETECTION
// ============================================================

/**
 * Detect circular trait references
 * AC: @trait-edge-cases ac-2
 */
function detectTraitCycles(
  items: LoadedSpecItem[],
  index: ReferenceIndex,
): TraitCycleError[] {
  const errors: TraitCycleError[] = [];
  const traits = items.filter((item) => item.type === "trait");

  // Build adjacency list: trait ULID → trait ULIDs it references
  const graph = new Map<string, string[]>();
  const traitInfo = new Map<string, { ref: string; title: string }>();

  for (const trait of traits) {
    const ref = trait.slugs?.[0]
      ? `@${trait.slugs[0]}`
      : `@${trait._ulid.slice(0, 8)}`;
    traitInfo.set(trait._ulid, { ref, title: trait.title });

    const dependencies: string[] = [];
    if (trait.traits && trait.traits.length > 0) {
      for (const traitRef of trait.traits) {
        const result = index.resolve(traitRef);
        if (result.ok) {
          dependencies.push(result.ulid);
        }
      }
    }
    graph.set(trait._ulid, dependencies);
  }

  // DFS-based cycle detection
  const visiting = new Set<string>();
  const visited = new Set<string>();

  function dfs(ulid: string, path: string[]): string[] | null {
    if (visiting.has(ulid)) {
      // Found a cycle - return the cycle path
      const cycleStart = path.indexOf(ulid);
      return path.slice(cycleStart);
    }

    if (visited.has(ulid)) {
      return null; // Already checked this path
    }

    visiting.add(ulid);
    path.push(ulid);

    const dependencies = graph.get(ulid) || [];
    for (const depUlid of dependencies) {
      const cycle = dfs(depUlid, path);
      if (cycle) {
        return cycle;
      }
    }

    visiting.delete(ulid);
    visited.add(ulid);
    path.pop();

    return null;
  }

  // Check each trait for cycles
  for (const trait of traits) {
    if (!visited.has(trait._ulid)) {
      const cycle = dfs(trait._ulid, []);
      if (cycle) {
        const info = traitInfo.get(cycle[0]);
        if (info) {
          const cycleRefs = cycle.map((ulid) => {
            const cycleInfo = traitInfo.get(ulid);
            return cycleInfo ? cycleInfo.ref : `@${ulid.slice(0, 8)}`;
          });

          errors.push({
            traitRef: info.ref,
            traitTitle: info.title,
            cycle: cycleRefs,
            message: `Circular trait reference: ${cycleRefs.join(" → ")} → ${cycleRefs[0]}`,
          });
        }

        // Mark all traits in cycle as visited to avoid duplicate errors
        for (const ulid of cycle) {
          visited.add(ulid);
        }
      }
    }
  }

  return errors;
}

// ============================================================
// COMPLETENESS VALIDATION
// ============================================================

/**
 * Recursively find all test files in a directory
 */
async function findTestFilesRecursive(dir: string): Promise<string[]> {
  const testFiles: string[] = [];

  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        // Recurse into subdirectories
        const subFiles = await findTestFilesRecursive(fullPath);
        testFiles.push(...subFiles);
      } else if (
        entry.isFile() &&
        (entry.name.endsWith(".test.ts") || entry.name.endsWith(".test.js"))
      ) {
        testFiles.push(fullPath);
      }
    }
  } catch {
    // Directory doesn't exist or can't be read - return empty
  }

  return testFiles;
}

/**
 * Scan test files for AC annotations to build coverage index.
 * Recursively scans all subdirectories under tests/.
 * Returns a Set of covered ACs in format "@spec-ref ac-N"
 */
export async function scanTestCoverage(rootDir: string): Promise<Set<string>> {
  const coveredACs = new Set<string>();
  const testsDir = path.join(rootDir, "tests");

  try {
    // Check if tests directory exists
    await fs.access(testsDir);

    // Recursively find all test files
    const testFiles = await findTestFilesRecursive(testsDir);

    for (const filePath of testFiles) {
      const content = await fs.readFile(filePath, "utf-8");

      // Match AC annotations: // AC: @spec-ref ac-N
      // Also handle multiple ACs on one line: // AC: @spec-ref ac-1, ac-2
      const acPattern =
        /\/\/\s*AC:\s*(@[\w-]+)(?:\s+(ac-\d+(?:\s*,\s*ac-\d+)*))?/g;
      let match;

      while ((match = acPattern.exec(content)) !== null) {
        const specRef = match[1]; // @spec-ref
        const acList = match[2]; // "ac-1, ac-2" or just "ac-1" or undefined

        if (acList) {
          // Split by comma and trim
          const acs = acList.split(",").map((ac) => ac.trim());
          for (const ac of acs) {
            coveredACs.add(`${specRef} ${ac}`);
          }
        } else {
          // No specific AC mentioned, just the spec ref
          // We'll consider this as generic coverage
          coveredACs.add(specRef);
        }
      }
    }
  } catch (_err) {
    // Tests directory doesn't exist or can't be read - that's ok
  }

  return coveredACs;
}

/**
 * Compute coverage status for acceptance criteria of a spec item.
 * Shared utility used by both daemon API and JSON export.
 *
 * @param item - The spec item containing acceptance_criteria
 * @param coveredACs - Set of covered AC references from scanTestCoverage()
 * @returns Array of ACs with covered field populated
 */
export function computeACCoverage<
  T extends { id: string; given: string; when: string; then: string },
>(
  item: { _ulid: string; slugs?: string[]; acceptance_criteria?: T[] },
  coveredACs: Set<string>,
): Array<T & { covered: boolean }> {
  if (!item.acceptance_criteria || item.acceptance_criteria.length === 0) {
    return [];
  }

  return item.acceptance_criteria.map((ac, index) => {
    const acId = `ac-${index + 1}`;
    const possibleRefs: string[] = [];

    // Try with primary slug
    if (item.slugs && item.slugs.length > 0) {
      possibleRefs.push(`@${item.slugs[0]} ${acId}`);
      possibleRefs.push(`@${item.slugs[0]}`);
    }

    // Try with ULID (short form)
    possibleRefs.push(`@${item._ulid.slice(0, 8)} ${acId}`);
    possibleRefs.push(`@${item._ulid.slice(0, 8)}`);

    const covered = possibleRefs.some((ref) => coveredACs.has(ref));
    return { ...ac, covered };
  });
}

/**
 * Check spec items for completeness
 * AC: @spec-completeness ac-1, ac-2, ac-3
 * AC: @trait-validation ac-1, ac-2, ac-3
 */
async function checkCompleteness(
  items: LoadedSpecItem[],
  _index: ReferenceIndex,
  rootDir: string,
  traitIndex?: TraitIndex,
): Promise<CompletenessWarning[]> {
  const warnings: CompletenessWarning[] = [];

  // Scan test files for AC coverage
  const coveredACs = await scanTestCoverage(rootDir);

  for (const item of items) {
    const itemRef = item.slugs?.[0]
      ? `@${item.slugs[0]}`
      : `@${item._ulid.slice(0, 8)}`;
    const isTrait = item.type === "trait";

    // AC: @spec-completeness ac-1
    // AC: @trait-type ac-2 - Traits should have acceptance criteria for completeness
    // Check for missing acceptance criteria
    if (!item.acceptance_criteria || item.acceptance_criteria.length === 0) {
      warnings.push({
        type: "missing_acceptance_criteria",
        itemRef,
        itemTitle: item.title,
        message: `${isTrait ? "Trait" : "Item"} ${itemRef} has no acceptance criteria`,
      });
    }

    // AC: @spec-completeness ac-2
    // AC: @trait-type ac-3 - Traits should have description for completeness
    // Check for missing description
    if (!item.description || item.description.trim() === "") {
      warnings.push({
        type: "missing_description",
        itemRef,
        itemTitle: item.title,
        message: `${isTrait ? "Trait" : "Item"} ${itemRef} has no description`,
      });
    }

    // AC: @spec-completeness ac-3
    // Check for status inconsistency between parent and children
    if (item.status?.implementation === "implemented") {
      // Check if this item has children with not_started status
      const childFields = [
        "modules",
        "features",
        "requirements",
        "constraints",
        "epics",
        "themes",
        "capabilities",
      ];

      for (const field of childFields) {
        const children = (item as any)[field];
        if (Array.isArray(children)) {
          for (const child of children) {
            if (child.status?.implementation === "not_started") {
              const childRef = child.slugs?.[0]
                ? `@${child.slugs[0]}`
                : `@${child._ulid?.slice(0, 8) || "unknown"}`;
              warnings.push({
                type: "status_inconsistency",
                itemRef,
                itemTitle: item.title,
                message: `Parent ${itemRef} is implemented but child ${childRef} is not_started`,
                details: `Child: ${child.title}`,
              });
            }
          }
        }
      }
    }

    // Check for test coverage of acceptance criteria
    if (item.acceptance_criteria && item.acceptance_criteria.length > 0) {
      const uncoveredACs: string[] = [];

      for (const ac of item.acceptance_criteria) {
        // Build all possible references for this AC
        const possibleRefs: string[] = [];

        // Try with primary slug
        if (item.slugs && item.slugs.length > 0) {
          possibleRefs.push(`@${item.slugs[0]} ${ac.id}`);
          // Also check for just the slug without specific AC
          possibleRefs.push(`@${item.slugs[0]}`);
        }

        // Try with ULID (short form)
        possibleRefs.push(`@${item._ulid.slice(0, 8)} ${ac.id}`);
        possibleRefs.push(`@${item._ulid.slice(0, 8)}`);

        // Check if any of these references are covered
        const isCovered = possibleRefs.some((ref) => coveredACs.has(ref));

        if (!isCovered) {
          uncoveredACs.push(ac.id);
        }
      }

      // Only warn if there are uncovered ACs
      if (uncoveredACs.length > 0) {
        warnings.push({
          type: "missing_test_coverage",
          itemRef,
          itemTitle: item.title,
          message: `Item ${itemRef} has ${uncoveredACs.length} AC(s) without test coverage`,
          details: `Uncovered: ${uncoveredACs.join(", ")}`,
        });
      }
    }

    // AC: @trait-validation ac-1, ac-2
    // Check for test coverage of trait acceptance criteria
    if (traitIndex && item.traits && item.traits.length > 0) {
      const inheritedACs = traitIndex.getInheritedAC(item._ulid);
      const uncoveredTraitACs: Array<{ traitSlug: string; acId: string }> = [];

      for (const { trait, ac } of inheritedACs) {
        // Build all possible references for this trait AC
        const possibleRefs: string[] = [];

        // Try with trait slug
        possibleRefs.push(`@${trait.slug} ${ac.id}`);
        possibleRefs.push(`@${trait.slug}`);

        // Try with trait ULID (short form)
        possibleRefs.push(`@${trait.ulid.slice(0, 8)} ${ac.id}`);
        possibleRefs.push(`@${trait.ulid.slice(0, 8)}`);

        // Check if any of these references are covered
        const isCovered = possibleRefs.some((ref) => coveredACs.has(ref));

        if (!isCovered) {
          uncoveredTraitACs.push({ traitSlug: trait.slug, acId: ac.id });
        }
      }

      // Only warn if there are uncovered trait ACs
      if (uncoveredTraitACs.length > 0) {
        const details = uncoveredTraitACs
          .map(({ traitSlug, acId }) => `@${traitSlug} ${acId}`)
          .join(", ");
        warnings.push({
          type: "missing_test_coverage",
          itemRef,
          itemTitle: item.title,
          message: `Item ${itemRef} has ${uncoveredTraitACs.length} inherited trait AC(s) without test coverage`,
          details: `Uncovered trait ACs: ${details}`,
        });
      }
    }

    // AC: @trait-retrospective ac-2, ac-3
    // Check retrospective specs have required verification metadata
    const isRetrospective = item.traits?.includes("@trait-retrospective");
    if (isRetrospective) {
      const isImplementedOrVerified =
        item.status?.implementation === "implemented" ||
        item.status?.implementation === "verified";

      // AC: @trait-retrospective ac-2
      // Retrospective specs with implemented/verified status must have verification metadata
      if (isImplementedOrVerified) {
        if (!item.verified_at || !item.verified_by) {
          warnings.push({
            type: "status_inconsistency",
            itemRef,
            itemTitle: item.title,
            message: `Retrospective spec ${itemRef} is ${item.status?.implementation} but missing verified_at/verified_by`,
            details:
              "Specs using @trait-retrospective must have verified_at and verified_by fields when marked as implemented or verified",
          });
        }
      }

      // Inverse validation: If verification metadata exists, status should be implemented/verified
      if ((item.verified_at || item.verified_by) && !isImplementedOrVerified) {
        warnings.push({
          type: "status_inconsistency",
          itemRef,
          itemTitle: item.title,
          message: `Retrospective spec ${itemRef} has verification metadata but status is not implemented/verified`,
          details:
            "Retrospective specs with verified_at/verified_by should have implementation status set to 'implemented' or 'verified'",
        });
      }
    }
  }

  return warnings;
}

// ============================================================
// AUTOMATION VALIDATION
// ============================================================

/**
 * Check task automation status for warnings
 * AC: @task-automation-eligibility ac-21, ac-23
 */
function checkAutomationEligibility(
  tasks: LoadedTask[],
  index: ReferenceIndex,
): CompletenessWarning[] {
  const warnings: CompletenessWarning[] = [];

  for (const task of tasks) {
    const taskRef = task.slugs?.[0]
      ? `@${task.slugs[0]}`
      : `@${task._ulid.slice(0, 8)}`;

    // AC: @task-automation-eligibility ac-21
    // Warn if eligible but no spec_ref
    if (task.automation === "eligible" && !task.spec_ref) {
      warnings.push({
        type: "automation_eligible_no_spec",
        itemRef: taskRef,
        itemTitle: task.title,
        message: `Task ${taskRef} is automation: eligible but has no spec_ref - eligible tasks should have linked specs`,
      });
    }

    // AC: @task-automation-eligibility ac-23
    // Warn if eligible but spec_ref doesn't resolve
    if (task.automation === "eligible" && task.spec_ref) {
      const specResult = index.resolve(task.spec_ref);
      if (!specResult.ok) {
        warnings.push({
          type: "automation_eligible_no_spec",
          itemRef: taskRef,
          itemTitle: task.title,
          message: `Task ${taskRef} is automation: eligible but spec_ref ${task.spec_ref} cannot be resolved`,
        });
      }
    }
  }

  return warnings;
}

// ============================================================
// MAIN VALIDATION
// ============================================================

/**
 * Run full validation on a kspec project
 */
export async function validate(
  ctx: KspecContext,
  options: ValidateOptions = {},
): Promise<ValidationResult> {
  // Default: run all checks
  const runSchema = options.schema !== false;
  const runRefs = options.refs !== false;
  const runOrphans = options.orphans !== false;
  const runCompleteness = options.completeness !== false;

  const result: ValidationResult = {
    valid: true,
    schemaErrors: [],
    refErrors: [],
    refWarnings: [],
    orphans: [],
    completenessWarnings: [],
    traitCycleErrors: [],
    stats: {
      filesChecked: 0,
      itemsChecked: 0,
      tasksChecked: 0,
    },
  };

  const allTasks: LoadedTask[] = [];
  const allItems: LoadedSpecItem[] = [];

  // Validate manifest
  if (ctx.manifestPath && runSchema) {
    const manifestErrors = await validateManifestFile(ctx.manifestPath);
    result.schemaErrors.push(...manifestErrors);
    result.stats.filesChecked++;
  }

  // Load items from manifest (traits, inline modules, etc.)
  if (ctx.manifest && ctx.manifestPath) {
    const manifestItems = extractItemsFromRaw(ctx.manifest, ctx.manifestPath);
    allItems.push(...manifestItems);
    result.stats.itemsChecked += manifestItems.length;
  }

  // Find and validate task files
  const taskFiles = await findTaskFiles(ctx.rootDir);
  const specTaskFiles = await findTaskFiles(path.join(ctx.rootDir, "spec"));
  const allTaskFiles = [...new Set([...taskFiles, ...specTaskFiles])];

  for (const taskFile of allTaskFiles) {
    if (runSchema) {
      const taskErrors = await validateTasksFile(taskFile);
      result.schemaErrors.push(...taskErrors);
    }
    result.stats.filesChecked++;

    // Load tasks for ref validation
    try {
      const raw = await readYamlFile<unknown>(taskFile);
      let taskList: unknown[] = [];

      if (Array.isArray(raw)) {
        taskList = raw;
      } else if (raw && typeof raw === "object" && "tasks" in raw) {
        taskList = (raw as { tasks: unknown[] }).tasks || [];
      }

      for (const t of taskList) {
        const parsed = TaskSchema.safeParse(t);
        if (parsed.success) {
          allTasks.push({ ...parsed.data, _sourceFile: taskFile });
          result.stats.tasksChecked++;
        }
      }
    } catch {
      // Already reported in schema validation
    }
  }

  // Validate spec files (from includes)
  if (ctx.manifest && ctx.manifestPath) {
    const manifestDir = path.dirname(ctx.manifestPath);
    const includes = ctx.manifest.includes || [];

    for (const include of includes) {
      const expandedPaths = await expandIncludePattern(include, manifestDir);

      for (const filePath of expandedPaths) {
        if (runSchema) {
          const specErrors = await validateSpecFile(filePath);
          result.schemaErrors.push(...specErrors);
        }
        result.stats.filesChecked++;

        // Load items for ref validation
        try {
          const items = await loadSpecFile(filePath);
          allItems.push(...items);
          result.stats.itemsChecked += items.length;
        } catch {
          // Already reported in schema validation
        }
      }
    }
  }

  // Load meta items for reference validation
  // AC: @agent-definitions ac-agent-3
  const metaCtx = await loadMetaContext(ctx);
  const allMetaItems = [
    ...metaCtx.agents,
    ...metaCtx.workflows,
    ...metaCtx.conventions,
    ...metaCtx.observations,
  ];

  // Load plans for reference validation
  // AC: @plan-validation ac-10
  const allPlans = await loadPlans(ctx);

  // Reference validation
  if (
    runRefs &&
    (allTasks.length > 0 ||
      allItems.length > 0 ||
      allMetaItems.length > 0 ||
      allPlans.length > 0)
  ) {
    const index = new ReferenceIndex(
      allTasks,
      allItems,
      allMetaItems,
      allPlans,
    );
    const refResult = validateRefs(index, allTasks, allItems);
    result.refErrors = refResult.errors;
    result.refWarnings = refResult.warnings;

    // AC: @trait-edge-cases ac-2
    // Detect circular trait references
    result.traitCycleErrors = detectTraitCycles(allItems, index);

    // Orphan detection
    if (runOrphans) {
      result.orphans = findOrphans(allTasks, allItems, index);
    }

    // Completeness validation
    // AC: @spec-completeness ac-1, ac-2, ac-3
    // AC: @trait-validation ac-3
    if (runCompleteness) {
      // Build trait index for trait AC coverage validation
      const traitIndex = new TraitIndex(allItems, index);
      result.completenessWarnings = await checkCompleteness(
        allItems,
        index,
        ctx.rootDir,
        traitIndex,
      );

      // AC: @task-automation-eligibility ac-21, ac-23
      // Check automation eligibility warnings for tasks
      const automationWarnings = checkAutomationEligibility(allTasks, index);
      result.completenessWarnings.push(...automationWarnings);
    }
  }

  // Meta manifest validation (AC-meta-manifest-2, AC-meta-manifest-3)
  const metaManifestPath = await findMetaManifest(ctx.specDir);
  if (metaManifestPath) {
    // Use metaCtx already loaded above
    result.metaStats = {
      agents: metaCtx.agents.length,
      workflows: metaCtx.workflows.length,
      conventions: metaCtx.conventions.length,
      observations: metaCtx.observations.length,
    };

    // Validate meta manifest schema with strict ULID validation
    if (runSchema) {
      const metaErrors = await validateMetaManifestFile(metaManifestPath);
      // Prefix all meta errors with "meta:"
      for (const err of metaErrors) {
        err.path = err.path ? `meta:${err.path}` : "meta:";
      }
      result.schemaErrors.push(...metaErrors);
      result.stats.filesChecked++;
    }
  }

  // Set valid flag
  result.valid =
    result.schemaErrors.length === 0 &&
    result.refErrors.length === 0 &&
    result.traitCycleErrors.length === 0;

  return result;
}

import * as path from "node:path";
import chalk from "chalk";
import type { Command } from "commander";
import type { LoadedSpecItem, LoadedTask } from "../../parser/index.js";
import {
  AlignmentIndex,
  type AlignmentWarning,
  type CompletenessWarning,
  type ConventionValidationResult,
  expandIncludePattern,
  type FixResult,
  findTaskFiles,
  fixFiles,
  initContext,
  loadAllItems,
  loadAllTasks,
  loadMetaContext,
  ReferenceIndex,
  type ValidationResult,
  validate,
  validateConventions,
} from "../../parser/index.js";
import {
  type SkillValidationResult,
  validateSkills,
} from "../../parser/validate-skills.js";
import { validation as validationStrings } from "../../strings/index.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, output } from "../output.js";

/**
 * Staleness warning types
 * AC: @stale-status-detection
 */
interface StalenessWarning {
  type:
    | "parent-pending-children-done"
    | "spec-implemented-no-task"
    | "task-done-spec-not-started"
    | "automation-blocking";
  message: string;
  refs: string[];
}

/**
 * Check for stale status mismatches between specs and tasks
 * AC: @stale-status-detection ac-1, ac-2, ac-3
 */
function checkStaleness(
  items: LoadedSpecItem[],
  tasks: LoadedTask[],
  refIndex: ReferenceIndex,
): StalenessWarning[] {
  const warnings: StalenessWarning[] = [];

  // AC: @stale-status-detection ac-1 (parent-pending-children-done)
  // Check if task with dependencies is pending but all dependencies are completed
  for (const task of tasks) {
    // Only check pending/in_progress tasks with dependencies
    if (task.status !== "pending" && task.status !== "in_progress") continue;
    if (!task.depends_on || task.depends_on.length === 0) continue;

    // Resolve all dependency tasks
    const depTasks = task.depends_on
      .map((depRef) => {
        const result = refIndex.resolve(depRef);
        if (!result.ok) return null;
        return tasks.find((t) => t._ulid === result.ulid);
      })
      .filter((t): t is LoadedTask => t !== null);

    if (depTasks.length === 0) continue;

    // Check if all dependencies are completed and their linked specs are implemented
    const allDepsDone = depTasks.every((depTask) => {
      if (depTask.status !== "completed") return false;

      // If the dep task has a spec_ref, check if that spec is implemented
      if (depTask.spec_ref) {
        const result = refIndex.resolve(depTask.spec_ref);
        if (!result.ok) return true; // Missing spec ref doesn't block
        const spec = items.find((item) => item._ulid === result.ulid);
        return spec?.status?.implementation === "implemented";
      }
      return true;
    });

    if (allDepsDone) {
      const taskRef = task.slugs[0] || refIndex.shortUlid(task._ulid);
      warnings.push({
        type: "parent-pending-children-done",
        message: `Task @${taskRef} is ${task.status} but all dependencies are completed. Consider completing or reviewing.`,
        refs: [task._ulid],
      });
    }
  }

  // AC: @stale-status-detection ac-2 (spec-implemented-no-task)
  // Check if spec is implemented but has no completed tasks
  for (const item of items) {
    if (item.status?.implementation !== "implemented") continue;

    // AC: @trait-retrospective ac-1
    // Skip retrospective specs from staleness warnings
    const isRetrospective = item.traits?.includes("@trait-retrospective");
    if (isRetrospective) continue;

    // Find completed tasks that reference this spec
    const completedTasks = tasks.filter((task) => {
      if (task.status !== "completed" || !task.spec_ref) return false;
      const result = refIndex.resolve(task.spec_ref);
      return result.ok && result.ulid === item._ulid;
    });

    if (completedTasks.length === 0) {
      const specRef = item.slugs[0] || refIndex.shortUlid(item._ulid);
      warnings.push({
        type: "spec-implemented-no-task",
        message: `Spec @${specRef} is implemented but has no completed tasks. Verify implementation or link existing task.`,
        refs: [item._ulid],
      });
    }
  }

  // AC: @stale-status-detection ac-3 (task-done-spec-not-started)
  // Check if task is completed but spec is still not_started
  for (const task of tasks) {
    if (task.status !== "completed") continue;
    if (!task.spec_ref) continue;

    // Resolve spec reference
    const result = refIndex.resolve(task.spec_ref);
    if (!result.ok) continue;

    const spec = items.find((item) => item._ulid === result.ulid);
    if (!spec) continue;

    if (spec.status?.implementation === "not_started") {
      const taskRef = task.slugs[0] || refIndex.shortUlid(task._ulid);
      const specRef = spec.slugs[0] || refIndex.shortUlid(spec._ulid);
      warnings.push({
        type: "task-done-spec-not-started",
        message: `Task @${taskRef} completed but spec @${specRef} is not_started. Update spec status.`,
        refs: [task._ulid, spec._ulid],
      });
    }
  }

  // AC: @validation ac-1
  // Check for manual_only parents blocking eligible children
  for (const parentTask of tasks) {
    if (parentTask.automation !== "manual_only") continue;

    // Find tasks that depend on this parent
    const dependentTasks = tasks.filter((t) =>
      t.depends_on?.some((depRef) => {
        const result = refIndex.resolve(depRef);
        return result.ok && result.ulid === parentTask._ulid;
      }),
    );

    // Filter for eligible children
    const eligibleChildren = dependentTasks.filter(
      (t) => t.automation === "eligible",
    );

    if (eligibleChildren.length > 0) {
      const parentRef =
        parentTask.slugs[0] || refIndex.shortUlid(parentTask._ulid);
      const childRefs = eligibleChildren.map(
        (c) => `@${c.slugs[0] || refIndex.shortUlid(c._ulid)}`,
      );

      warnings.push({
        type: "automation-blocking",
        message: `Task @${parentRef} is manual_only and blocks ${eligibleChildren.length} eligible child task(s): ${childRefs.join(", ")}`,
        refs: [parentTask._ulid, ...eligibleChildren.map((c) => c._ulid)],
      });
    }
  }

  return warnings;
}

/**
 * Format staleness warnings for display
 * AC: @stale-status-detection ac-4
 */
function formatStalenessWarnings(
  warnings: StalenessWarning[],
  verbose: boolean,
): void {
  if (warnings.length === 0) {
    console.log(chalk.green("Staleness: OK"));
    return;
  }

  console.log(chalk.yellow(`\nStaleness warnings: ${warnings.length}`));

  // Group by type
  const parentPending = warnings.filter(
    (w) => w.type === "parent-pending-children-done",
  );
  const specNoTask = warnings.filter(
    (w) => w.type === "spec-implemented-no-task",
  );
  const taskDoneSpecNot = warnings.filter(
    (w) => w.type === "task-done-spec-not-started",
  );
  const automationBlocking = warnings.filter(
    (w) => w.type === "automation-blocking",
  );

  if (parentPending.length > 0) {
    console.log(
      chalk.yellow(`  Parent pending, children done: ${parentPending.length}`),
    );
    const shown = verbose ? parentPending : parentPending.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && parentPending.length > 3) {
      console.log(chalk.gray(`    ... and ${parentPending.length - 3} more`));
    }
  }

  if (specNoTask.length > 0) {
    console.log(
      chalk.yellow(`  Spec implemented, no task: ${specNoTask.length}`),
    );
    const shown = verbose ? specNoTask : specNoTask.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && specNoTask.length > 3) {
      console.log(chalk.gray(`    ... and ${specNoTask.length - 3} more`));
    }
  }

  if (taskDoneSpecNot.length > 0) {
    console.log(
      chalk.yellow(`  Task done, spec not started: ${taskDoneSpecNot.length}`),
    );
    const shown = verbose ? taskDoneSpecNot : taskDoneSpecNot.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && taskDoneSpecNot.length > 3) {
      console.log(chalk.gray(`    ... and ${taskDoneSpecNot.length - 3} more`));
    }
  }

  if (automationBlocking.length > 0) {
    console.log(
      chalk.yellow(`  Automation blocking: ${automationBlocking.length}`),
    );
    const shown = verbose ? automationBlocking : automationBlocking.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
    if (!verbose && automationBlocking.length > 3) {
      console.log(
        chalk.gray(`    ... and ${automationBlocking.length - 3} more`),
      );
    }
  }
}

/**
 * Format convention validation results for display
 * AC: @convention-definitions ac-3, ac-4
 */
function formatConventionValidationResult(
  result: ConventionValidationResult,
): void {
  if (result.valid && result.skipped.length === 0) {
    console.log(chalk.green("Conventions: OK"));
    return;
  }

  // AC: @convention-definitions ac-4
  // Skipped prose conventions
  if (result.skipped.length > 0) {
    for (const domain of result.skipped) {
      console.log(chalk.gray(`ℹ Skipping prose convention: ${domain}`));
    }
  }

  // AC: @convention-definitions ac-3
  // Validation errors
  if (result.errors.length > 0) {
    console.log(chalk.red(`\nConvention violations: ${result.errors.length}`));
    for (const err of result.errors) {
      console.log(chalk.red(`  ✗ ${err.domain}`));
      console.log(chalk.gray(`    ${err.message}`));
      if (err.expected) {
        console.log(chalk.gray(`    Expected: ${err.expected}`));
      }
      if (err.location) {
        console.log(chalk.gray(`    Location: ${err.location}`));
      }
    }
  } else {
    console.log(chalk.green("\nConventions: OK"));
  }

  // Stats
  console.log(
    chalk.gray(`\nConventions checked: ${result.stats.conventionsChecked}`),
  );
  console.log(
    chalk.gray(`Conventions skipped: ${result.stats.conventionsSkipped}`),
  );
}

/**
 * Format skill validation results for display
 */
function formatSkillValidationResult(
  result: SkillValidationResult,
  verbose: boolean,
): void {
  if (result.filesChecked === 0) {
    console.log(chalk.gray("Skills: No skill files found"));
    return;
  }

  if (result.valid) {
    console.log(
      chalk.green(`Skills: OK (${result.filesChecked} files checked)`),
    );
    return;
  }

  console.log(chalk.red(`\nSkill validation errors: ${result.errors.length}`));
  console.log(chalk.gray(`Files checked: ${result.filesChecked}`));

  // Group errors by file
  const errorsByFile = new Map<string, typeof result.errors>();
  for (const err of result.errors) {
    const existing = errorsByFile.get(err.file) || [];
    existing.push(err);
    errorsByFile.set(err.file, existing);
  }

  for (const [file, errors] of errorsByFile.entries()) {
    console.log(chalk.yellow(`\n  ${file}:`));
    const shown = verbose ? errors : errors.slice(0, 5);
    for (const err of shown) {
      const location = err.line ? `:${err.line}` : "";
      console.log(chalk.red(`    ✗ ${err.type}${location}`));
      console.log(chalk.gray(`      ${err.message}`));
    }
    if (!verbose && errors.length > 5) {
      console.log(chalk.gray(`    ... and ${errors.length - 5} more`));
    }
  }
}

/**
 * Format completeness warnings for display
 * AC: @spec-completeness ac-4
 */
function formatCompletenessWarnings(
  warnings: CompletenessWarning[],
  verbose: boolean,
): void {
  if (warnings.length === 0) {
    console.log(chalk.green("Completeness: OK"));
    return;
  }

  console.log(chalk.yellow(`\nCompleteness warnings: ${warnings.length}`));

  // Group by type
  const missingAC = warnings.filter(
    (w) => w.type === "missing_acceptance_criteria",
  );
  const missingDesc = warnings.filter((w) => w.type === "missing_description");
  const statusMismatch = warnings.filter(
    (w) => w.type === "status_inconsistency",
  );
  const missingTestCoverage = warnings.filter(
    (w) => w.type === "missing_test_coverage",
  );
  const automationNoSpec = warnings.filter(
    (w) => w.type === "automation_eligible_no_spec",
  );

  // AC: @spec-completeness ac-4
  // Show summary with counts by issue type
  if (missingAC.length > 0) {
    console.log(
      chalk.yellow(`  Missing acceptance criteria: ${missingAC.length}`),
    );
    const shown = verbose ? missingAC : missingAC.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.gray(`    ○ ${w.itemRef} - ${w.itemTitle}`));
    }
    if (!verbose && missingAC.length > 3) {
      console.log(chalk.gray(`    ... and ${missingAC.length - 3} more`));
    }
  }

  if (missingDesc.length > 0) {
    console.log(chalk.yellow(`  Missing descriptions: ${missingDesc.length}`));
    const shown = verbose ? missingDesc : missingDesc.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.gray(`    ○ ${w.itemRef} - ${w.itemTitle}`));
    }
    if (!verbose && missingDesc.length > 3) {
      console.log(chalk.gray(`    ... and ${missingDesc.length - 3} more`));
    }
  }

  if (statusMismatch.length > 0) {
    console.log(
      chalk.yellow(`  Status inconsistencies: ${statusMismatch.length}`),
    );
    for (const w of statusMismatch) {
      console.log(chalk.yellow(`    ! ${w.message}`));
      if (w.details) {
        console.log(chalk.gray(`      ${w.details}`));
      }
    }
  }

  if (missingTestCoverage.length > 0) {
    console.log(
      chalk.yellow(`  Missing test coverage: ${missingTestCoverage.length}`),
    );
    const shown = verbose
      ? missingTestCoverage
      : missingTestCoverage.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.itemRef} - ${w.itemTitle}`));
      if (w.details) {
        console.log(chalk.gray(`      ${w.details}`));
      }
    }
    if (!verbose && missingTestCoverage.length > 3) {
      console.log(
        chalk.gray(`    ... and ${missingTestCoverage.length - 3} more`),
      );
    }
  }

  // AC: @task-automation-eligibility ac-21, ac-23
  if (automationNoSpec.length > 0) {
    console.log(
      chalk.yellow(`  Automation without spec: ${automationNoSpec.length}`),
    );
    const shown = verbose ? automationNoSpec : automationNoSpec.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.yellow(`    ! ${w.itemRef} - ${w.itemTitle}`));
      console.log(chalk.gray(`      ${w.message}`));
    }
    if (!verbose && automationNoSpec.length > 3) {
      console.log(
        chalk.gray(`    ... and ${automationNoSpec.length - 3} more`),
      );
    }
  }
}

/**
 * Format alignment warnings for display
 */
function formatAlignmentWarnings(
  warnings: AlignmentWarning[],
  verbose: boolean,
): void {
  if (warnings.length === 0) {
    console.log(chalk.green("Alignment: OK"));
    return;
  }

  console.log(chalk.yellow(`\nAlignment warnings: ${warnings.length}`));

  // Group by type
  const orphaned = warnings.filter((w) => w.type === "orphaned_spec");
  const mismatches = warnings.filter((w) => w.type === "status_mismatch");
  const stale = warnings.filter((w) => w.type === "stale_implementation");

  if (orphaned.length > 0) {
    console.log(
      chalk.yellow(`  Orphaned specs (no tasks): ${orphaned.length}`),
    );
    const shown = verbose ? orphaned : orphaned.slice(0, 3);
    for (const w of shown) {
      console.log(chalk.gray(`    ○ ${w.specTitle}`));
    }
    if (!verbose && orphaned.length > 3) {
      console.log(chalk.gray(`    ... and ${orphaned.length - 3} more`));
    }
  }

  if (mismatches.length > 0) {
    console.log(chalk.yellow(`  Status mismatches: ${mismatches.length}`));
    for (const w of mismatches) {
      console.log(chalk.yellow(`    ! ${w.specTitle}`));
      console.log(chalk.gray(`      ${w.message}`));
    }
  }

  if (stale.length > 0) {
    console.log(chalk.yellow(`  Stale implementation status: ${stale.length}`));
    for (const w of stale) {
      console.log(chalk.yellow(`    ! ${w.message}`));
    }
  }
}

/**
 * Format fix results for display
 */
function formatFixResult(result: FixResult): void {
  if (result.fixesApplied.length === 0) {
    console.log(chalk.gray("\nNo auto-fixable issues found."));
    return;
  }

  console.log(
    chalk.cyan(
      `\n✓ Applied ${result.fixesApplied.length} fix(es) to ${result.filesModified} file(s):`,
    ),
  );

  for (const fix of result.fixesApplied) {
    const typeLabel = {
      ulid_regenerated: "ULID regenerated",
      timestamp_added: "Timestamp added",
      status_added: "Status added",
    }[fix.type];

    const shortFile = path.basename(fix.file);
    console.log(chalk.cyan(`  ✓ ${shortFile}:${fix.path} - ${typeLabel}`));
  }

  if (result.errors.length > 0) {
    console.log(chalk.yellow(`\nFix errors: ${result.errors.length}`));
    for (const err of result.errors) {
      console.log(chalk.yellow(`  ! ${err.file}: ${err.message}`));
    }
  }
}

/**
 * Collect all files that can be fixed
 */
async function collectFixableFiles(ctx: {
  rootDir: string;
  specDir?: string;
  manifest?: { includes?: string[] } | null;
  manifestPath?: string | null;
}): Promise<string[]> {
  const files: string[] = [];

  // Task files (exclude test fixtures)
  const taskFiles = await findTaskFiles(ctx.rootDir);
  const specTaskFiles = await findTaskFiles(path.join(ctx.rootDir, "spec"));
  const allTaskFiles = [...new Set([...taskFiles, ...specTaskFiles])];
  files.push(
    ...allTaskFiles.filter(
      (f) => !f.includes("fixtures") && !f.includes("test"),
    ),
  );

  // Spec files from includes
  if (ctx.manifest && ctx.manifestPath) {
    const manifestDir = path.dirname(ctx.manifestPath);
    const includes = ctx.manifest.includes || [];

    for (const include of includes) {
      const expandedPaths = await expandIncludePattern(include, manifestDir);
      files.push(...expandedPaths);
    }
  }

  // Inbox file
  const inboxPath = path.join(ctx.rootDir, "spec", "kynetic.inbox.yaml");
  try {
    await import("node:fs/promises").then((fs) => fs.access(inboxPath));
    files.push(inboxPath);
  } catch {
    // Inbox file doesn't exist, skip
  }

  return [...new Set(files)];
}

/**
 * Format validation result for display
 */
function formatValidationResult(
  result: ValidationResult,
  verbose: boolean,
): void {
  // Header
  if (result.valid) {
    console.log(chalk.green.bold("✓ Validation passed"));
  } else {
    console.log(chalk.red.bold("✗ Validation failed"));
  }

  console.log(chalk.gray("─".repeat(40)));
  console.log(`Files checked: ${result.stats.filesChecked}`);
  console.log(`Items checked: ${result.stats.itemsChecked}`);
  console.log(`Tasks checked: ${result.stats.tasksChecked}`);

  // AC-meta-manifest-2: Display meta summary line
  if (result.metaStats) {
    console.log(
      `Meta: ${result.metaStats.agents} agents, ${result.metaStats.workflows} workflows, ${result.metaStats.conventions} conventions`,
    );
  }

  // Schema errors
  if (result.schemaErrors.length > 0) {
    console.log(chalk.red(`\nSchema errors: ${result.schemaErrors.length}`));
    for (const err of result.schemaErrors) {
      const location = err.path ? `${err.file}:${err.path}` : err.file;
      console.log(chalk.red(`  ✗ ${location}`));
      console.log(chalk.gray(`    ${err.message}`));
      if (verbose && err.details) {
        console.log(chalk.gray(`    ${JSON.stringify(err.details)}`));
      }
    }
  } else {
    console.log(chalk.green("\nSchema: OK"));
  }

  // Reference errors
  if (result.refErrors.length > 0) {
    console.log(chalk.red(`\nReference errors: ${result.refErrors.length}`));
    for (const err of result.refErrors) {
      const location = err.sourceFile
        ? `${err.sourceFile} (${err.field})`
        : `${err.sourceUlid?.slice(0, 8)} (${err.field})`;
      console.log(chalk.red(`  ✗ ${err.ref}`));
      console.log(chalk.gray(`    ${err.message}`));
      console.log(chalk.gray(`    in: ${location}`));
    }
  } else {
    console.log(chalk.green("References: OK"));
  }

  // Reference warnings (deprecated targets)
  if (result.refWarnings.length > 0) {
    console.log(
      chalk.yellow(`\nReference warnings: ${result.refWarnings.length}`),
    );
    const shown = verbose ? result.refWarnings : result.refWarnings.slice(0, 5);
    for (const warn of shown) {
      const location = warn.sourceFile
        ? `${warn.sourceFile} (${warn.field})`
        : `${warn.sourceUlid?.slice(0, 8)} (${warn.field})`;
      console.log(chalk.yellow(`  ⚠ ${warn.ref}`));
      console.log(chalk.gray(`    ${warn.message}`));
      console.log(chalk.gray(`    in: ${location}`));
    }
    if (!verbose && result.refWarnings.length > 5) {
      console.log(
        chalk.gray(
          `  ... and ${result.refWarnings.length - 5} more (use -v to see all)`,
        ),
      );
    }
  }

  // AC: @trait-edge-cases ac-2
  // Trait cycle errors
  if (result.traitCycleErrors.length > 0) {
    console.log(
      chalk.red(`\nTrait cycle errors: ${result.traitCycleErrors.length}`),
    );
    for (const err of result.traitCycleErrors) {
      console.log(chalk.red(`  ✗ ${err.traitRef} - ${err.traitTitle}`));
      console.log(chalk.gray(`    ${err.message}`));
    }
  }

  // Orphans (warnings, not errors)
  if (result.orphans.length > 0) {
    console.log(
      chalk.yellow(`\nOrphans (not referenced): ${result.orphans.length}`),
    );
    if (verbose) {
      for (const orphan of result.orphans) {
        console.log(
          chalk.yellow(
            `  ○ ${orphan.ulid.slice(0, 8)} [${orphan.type}] ${orphan.title}`,
          ),
        );
      }
    } else {
      // Show first few
      const shown = result.orphans.slice(0, 5);
      for (const orphan of shown) {
        console.log(
          chalk.yellow(
            `  ○ ${orphan.ulid.slice(0, 8)} [${orphan.type}] ${orphan.title}`,
          ),
        );
      }
      if (result.orphans.length > 5) {
        console.log(
          chalk.gray(
            `  ... and ${result.orphans.length - 5} more (use -v to see all)`,
          ),
        );
      }
    }
  }
}

/**
 * Register validate command
 */
export function registerValidateCommand(program: Command): void {
  program
    .command("validate")
    .description("Validate spec files")
    .option("--schema", "Check schema conformance only")
    .option("--refs", "Check reference resolution only")
    .option("--orphans", "Find orphaned items only")
    .option("--alignment", "Check spec-task alignment")
    .option(
      "--completeness",
      "Check spec completeness (missing AC, descriptions, status inconsistencies)",
    )
    .option("--conventions", "Validate conventions")
    .option(
      "--staleness",
      "Check for stale status mismatches between specs and tasks",
    )
    .option("--skills", "Validate skill files (.claude/skills/*/SKILL.md)")
    .option(
      "--fix",
      "Auto-fix issues where possible (invalid ULIDs, missing timestamps)",
    )
    .option("-v, --verbose", "Show detailed output")
    .option("--strict", "Treat orphans and staleness warnings as errors")
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(validationStrings.noManifest);
          console.log(validationStrings.initHint);
          process.exit(EXIT_CODES.ERROR);
        }

        // Track warnings from all sources for exit code determination
        let additionalWarningCount = 0;

        // Determine which checks to run
        const runAll =
          !options.schema &&
          !options.refs &&
          !options.orphans &&
          !options.alignment &&
          !options.completeness &&
          !options.conventions &&
          !options.skills;
        const validateOptions = {
          schema: runAll || options.schema,
          refs: runAll || options.refs,
          orphans: runAll || options.orphans,
          completeness: runAll || options.completeness,
        };

        const result = await validate(ctx, validateOptions);

        // In strict mode, orphans are errors
        if (options.strict && result.orphans.length > 0) {
          result.valid = false;
        }

        output(result, () => formatValidationResult(result, options.verbose));

        // Run auto-fix if requested
        if (options.fix) {
          const filesToFix = await collectFixableFiles(ctx);
          const fixResult = await fixFiles(filesToFix);
          formatFixResult(fixResult);

          // Re-run validation after fixes to show updated status
          if (fixResult.fixesApplied.length > 0) {
            console.log(validationStrings.revalidating);
            const revalidateResult = await validate(ctx, validateOptions);
            if (revalidateResult.valid) {
              console.log(validationStrings.nowPasses);
            } else {
              console.log(validationStrings.issuesRemain);
            }
            // Update result for exit code
            result.valid = revalidateResult.valid;
            result.schemaErrors = revalidateResult.schemaErrors;
            result.refErrors = revalidateResult.refErrors;
          }
        }

        // Run alignment check if requested or running all checks
        if (options.alignment || runAll) {
          const tasks = await loadAllTasks(ctx);
          const items = await loadAllItems(ctx);
          const refIndex = new ReferenceIndex(tasks, items);
          const alignmentIndex = new AlignmentIndex(tasks, items);
          alignmentIndex.buildLinks(refIndex);

          const alignmentWarnings = alignmentIndex.findAlignmentWarnings();
          formatAlignmentWarnings(alignmentWarnings, options.verbose);
          additionalWarningCount += alignmentWarnings.length;

          // Show alignment stats
          const stats = alignmentIndex.getStats();
          console.log(
            validationStrings.alignmentStats(
              stats.specsWithTasks,
              stats.totalSpecs,
              stats.alignedSpecs,
            ),
          );
        }

        // Show completeness warnings if any
        // AC: @spec-completeness ac-4
        if (result.completenessWarnings.length > 0) {
          formatCompletenessWarnings(
            result.completenessWarnings,
            options.verbose,
          );
        }

        // Run convention validation if requested
        // AC: @convention-definitions ac-3, ac-4
        if (options.conventions) {
          try {
            const metaCtx = await loadMetaContext(ctx);
            if (metaCtx && metaCtx.conventions.length > 0) {
              // For now, we just validate that conventions are well-formed
              // Full validation against actual content (commits, notes, etc.)
              // would require additional content gathering logic
              const conventionResult = validateConventions(
                metaCtx.conventions,
                {},
              );
              formatConventionValidationResult(conventionResult);

              if (!conventionResult.valid) {
                result.valid = false;
              }
            } else {
              console.log(
                chalk.gray("No conventions defined in meta manifest"),
              );
            }
          } catch (_err) {
            console.log(
              chalk.yellow(
                "Warning: Could not load meta manifest for convention validation",
              ),
            );
          }
        }

        // Run staleness checks if requested
        // AC: @stale-status-detection ac-4, ac-5
        let stalenessWarningCount = 0;
        if (options.staleness) {
          const tasks = await loadAllTasks(ctx);
          const items = await loadAllItems(ctx);
          const refIndex = new ReferenceIndex(tasks, items);

          const stalenessWarnings = checkStaleness(items, tasks, refIndex);
          formatStalenessWarnings(stalenessWarnings, options.verbose);
          stalenessWarningCount = stalenessWarnings.length;

          // AC: @stale-status-detection ac-5 (staleness-exit-code)
          // With --strict, staleness warnings cause validation failure
          if (options.strict && stalenessWarnings.length > 0) {
            result.valid = false;
          }
        }

        // Run skill file validation if requested or running all checks
        if (runAll || options.skills) {
          const skillResult = await validateSkills(ctx.rootDir);
          formatSkillValidationResult(skillResult, options.verbose);

          if (!skillResult.valid) {
            result.valid = false;
          }
        }

        // Determine exit code based on errors vs warnings
        // Errors: schema, refs, trait cycles, conventions, skills (result.valid = false)
        // Warnings: orphans, alignment, completeness, staleness, ref warnings
        const hasErrors = !result.valid;
        const hasWarnings =
          result.orphans.length > 0 ||
          result.refWarnings.length > 0 ||
          result.completenessWarnings.length > 0 ||
          additionalWarningCount > 0 ||
          stalenessWarningCount > 0;

        if (hasErrors) {
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        } else if (hasWarnings) {
          process.exit(EXIT_CODES.VALIDATION_WARNINGS);
        }
        // Otherwise exit 0 (success)
      } catch (err) {
        error(validationStrings.failed, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // Alias: kspec lint
  program
    .command("lint")
    .description("Alias for validate with style checks")
    .option("--schema", "Check schema conformance only")
    .option("--refs", "Check reference resolution only")
    .option("--orphans", "Find orphaned items only")
    .option(
      "--completeness",
      "Check spec completeness (missing AC, descriptions, status inconsistencies)",
    )
    .option(
      "--fix",
      "Auto-fix issues where possible (invalid ULIDs, missing timestamps)",
    )
    .option("-v, --verbose", "Show detailed output")
    .option("--strict", "Treat orphans as errors")
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(validationStrings.noManifest);
          process.exit(EXIT_CODES.ERROR);
        }

        const runAll =
          !options.schema &&
          !options.refs &&
          !options.orphans &&
          !options.completeness;
        const validateOptions = {
          schema: runAll || options.schema,
          refs: runAll || options.refs,
          orphans: runAll || options.orphans,
          completeness: runAll || options.completeness,
        };

        const result = await validate(ctx, validateOptions);

        if (options.strict && result.orphans.length > 0) {
          result.valid = false;
        }

        output(result, () => formatValidationResult(result, options.verbose));

        // Run auto-fix if requested
        if (options.fix) {
          const filesToFix = await collectFixableFiles(ctx);
          const fixResult = await fixFiles(filesToFix);
          formatFixResult(fixResult);

          // Re-run validation after fixes
          if (fixResult.fixesApplied.length > 0) {
            console.log(validationStrings.revalidating);
            const revalidateResult = await validate(ctx, validateOptions);
            if (revalidateResult.valid) {
              console.log(validationStrings.nowPasses);
            } else {
              console.log(validationStrings.issuesRemain);
            }
            result.valid = revalidateResult.valid;
          }
        }

        // Determine exit code based on errors vs warnings
        const hasErrors = !result.valid;
        const hasWarnings =
          result.orphans.length > 0 ||
          result.refWarnings.length > 0 ||
          result.completenessWarnings.length > 0;

        if (hasErrors) {
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        } else if (hasWarnings) {
          process.exit(EXIT_CODES.VALIDATION_WARNINGS);
        }
        // Otherwise exit 0 (success)
      } catch (err) {
        error(validationStrings.lintFailed, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

