  priority: z.number().int().min(1).max(5).default(3),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).default([]),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).default([]),

  // Timestamps (auto-populated if not provided)
  created_at: DateTimeSchema.default(() => new Date().toISOString()),
  started_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).default([]),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).default([]),

  // Automation eligibility (AC: @task-automation-eligibility ac-1, ac-2)
  // Optional - absent means unassessed
  automation: AutomationStatusSchema.optional(),
});

/**
 * Task input schema (for creating new tasks, some fields auto-generated)
 * All fields except title are optional - defaults will be applied
 */
export const TaskInputSchema = z.object({
  // Identity (auto-generated if not provided)
  _ulid: UlidSchema.optional(),
  slugs: z.array(SlugSchema).optional(),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.optional(),

  // Content
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(["auto", "manual"]).optional(),

  // Meta relationship
  meta_ref: RefSchema.nullable().optional(),

  // Plan relationship
  plan_ref: RefSchema.nullable().optional(),

  // Origin tracking
  origin: z.enum(["manual", "derived", "observation_promotion"]).optional(),

  // State
  status: TaskStatusSchema.optional(),
  blocked_by: z.array(z.string()).optional(),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).optional(),
  context: z.array(RefSchema).optional(),

  // Work metadata
  priority: z.number().int().min(1).max(5).optional(),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).optional(),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).optional(),

  // Timestamps
  created_at: DateTimeSchema.optional(),
  started_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).optional(),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).optional(),

  // Automation eligibility (AC: @task-automation-eligibility ac-1, ac-2, ac-13)
  automation: AutomationStatusSchema.optional(),
});

/**
 * Tasks file schema (collection of tasks)
 */
export const TasksFileSchema = z.object({
  kynetic_tasks: z.string().default("1.0"),
  tasks: z.array(TaskSchema),
});

export type Note = z.infer<typeof NoteSchema>;
export type Todo = z.infer<typeof TodoSchema>;
export type Task = z.infer<typeof TaskSchema>;
export type TaskInput = z.infer<typeof TaskInputSchema>;
export type TasksFile = z.infer<typeof TasksFileSchema>;

import { z } from "zod";

// Common types used across spec and task schemas

/**
 * ULID pattern - 26 character Crockford base32
 * Excludes I, L, O, U to avoid confusion with 1, 1, 0, V
 */
export const ulidPattern = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/**
 * Slug pattern - lowercase alphanumeric with hyphens
 */
export const slugPattern = /^[a-z][a-z0-9-]*$/;

/**
 * Reference pattern - @ prefix followed by slug or ULID (or short ULID)
 */
export const refPattern = /^@[a-zA-Z0-9-]+$/;

// Base schemas
export const UlidSchema = z.string().regex(ulidPattern, "Invalid ULID format");
export const SlugSchema = z.string().regex(slugPattern, "Invalid slug format");
export const RefSchema = z
  .string()
  .regex(refPattern, "Invalid reference format");

// Priority can be string or number
export const PrioritySchema = z.union([
  z.enum(["high", "medium", "low"]),
  z.number().int().min(1).max(5),
]);

// ISO 8601 date or datetime
export const DateTimeSchema = z.union([
  z.string().datetime(),
  z.string().date(),
]);

// Maturity status
export const MaturitySchema = z.enum([
  "draft",
  "proposed",
  "stable",
  "deferred",
  "deprecated",
]);

// Implementation status
export const ImplementationStatusSchema = z.enum([
  "not_started",
  "in_progress",
  "implemented",
  "verified",
]);

// Task status
export const TaskStatusSchema = z.enum([
  "pending",
  "in_progress",
  "pending_review",
  "blocked",
  "completed",
  "cancelled",
]);

// Task type
export const TaskTypeSchema = z.enum(["epic", "task", "bug", "spike", "infra"]);

// Item type
export const ItemTypeSchema = z.enum([
  "module",
  "feature",
  "requirement",
  "constraint",
  "decision",
  "task",
  "trait",
]);

// VCS reference
export const VcsRefSchema = z.object({
  ref: z.string(),
  type: z.enum(["branch", "tag", "commit"]).optional(),
});

export type Ulid = z.infer<typeof UlidSchema>;
export type Slug = z.infer<typeof SlugSchema>;
export type Ref = z.infer<typeof RefSchema>;
export type Priority = z.infer<typeof PrioritySchema>;
export type DateTime = z.infer<typeof DateTimeSchema>;
export type Maturity = z.infer<typeof MaturitySchema>;
export type ImplementationStatus = z.infer<typeof ImplementationStatusSchema>;
export type TaskStatus = z.infer<typeof TaskStatusSchema>;
export type TaskType = z.infer<typeof TaskTypeSchema>;
export type ItemType = z.infer<typeof ItemTypeSchema>;
export type VcsRef = z.infer<typeof VcsRefSchema>;

