                );
              }
              console.log("");
            }
          }
        }

        // Sync spec implementation status (unless --no-sync)
        if (options.sync !== false && foundTask.spec_ref) {
          const updatedTasks = tasks.map((t) =>
            t._ulid === updatedTask._ulid ? { ...t, ...updatedTask } : t,
