          executeOperation: async (foundTask, { ctx, index, options }) => {
            try {
              const taskDisplay = `${foundTask.title} (${index.shortUlid(foundTask._ulid)})`;

              if (options.dryRun) {
                return {
                  success: true,
                  message: `Would delete: ${taskDisplay}`,
