    60→setVerboseModeGetter(getVerboseMode);
    61→
    62→/**
    63→ * Auto-start daemon if configured and not already running
    64→ * AC: @daemon-server (implicit auto-start behavior)
    65→ */
    66→async function maybeAutoStartDaemon(): Promise<void> {
    67→  try {
    68→    // Load context to get daemon config
    69→    const context = await initContext();
    70→    const daemonConfig = context.manifest?.daemon;
    71→
    72→    // If daemon section missing entirely, auto_start defaults to true via schema
    73→    // Only skip if explicitly disabled
    74→    if (daemonConfig && daemonConfig.auto_start === false) {
    75→      return;
    76→    }
    77→
    78→    // Get port from config (schema defaults to 3456 if daemon section exists)
    79→    const port = daemonConfig?.port ?? 3456;
    80→
    81→    // Check if daemon is already running
    82→    const kspecDir = context.specDir;
    83→    const pidManager = new PidFileManager(kspecDir);
    84→
    85→    if (pidManager.isDaemonRunning()) {
    86→      // Already running, nothing to do
    87→      return;
    88→    }
    89→
    90→    // Get path to daemon entry point - resolve relative to installed package
    91→    const packageRoot = join(import.meta.dirname, '../../');
    92→    const daemonBinary = join(packageRoot, 'dist/daemon/index.js');
    93→    if (!existsSync(daemonBinary)) {
    94→      // Daemon not available, skip silently
    95→      return;
    96→    }
    97→
    98→    // Start daemon in background using current runtime
    99→    // Set BUN_ENV=production to prevent Bun dev mode HTML transformation
   100→    const child = spawn(process.execPath, [daemonBinary, '--port', String(port), '--kspec-dir', kspecDir], {
   101→      detached: true,
   102→      stdio: 'ignore',
   103→      cwd: process.cwd(),
   104→      env: { ...process.env, BUN_ENV: 'production' },
   105→    });
   106→
   107→    // Detach from parent
   108→    child.unref();
   109→
   110→    // Don't wait for daemon to start - let it happen in background
   111→  } catch {
   112→    // Errors during auto-start are non-fatal - continue with command
   113→  }
   114→}
   115→
   116→program
   117→  .name("kspec")
   118→  .description("Kynetic Spec - Structured specification format CLI")
   119→  .version(version)
   120→  .option("--json", "Output in JSON format")
   121→  .option("--debug-shadow", "Enable debug output for shadow operations")
   122→  .hook("preAction", async (thisCommand) => {
   123→    // Skip all hooks during batch dispatch — the batch handler manages modes itself
   124→    if (isBatchMode()) return;
   125→
   126→    // Check for --json and --debug-shadow flags at top level or on subcommand
   127→    const opts = thisCommand.opts();
   128→    if (opts.json) {
   129→      setJsonMode(true);
   130→    }
   131→    if (opts.debugShadow) {
   132→      setVerboseMode(true);
