   134→
   135→    // Auto-start daemon if configured and not running
   136→    // Skip for init, serve, and help commands
   137→    const commandName = thisCommand.name();
   138→    const skipCommands = ['init', 'serve', 'help', 'kspec'];
   139→
   140→    if (!skipCommands.includes(commandName)) {
   141→      await maybeAutoStartDaemon();
   142→    }
   143→  });
   144→
   145→// Register command groups
   146→registerTasksCommands(program);
   147→registerTaskCommands(program);
   148→registerSetupCommand(program);
   149→registerSessionCommands(program);
   150→registerInitCommand(program);
   151→
   152→// Register item commands first, then add trait subcommands to it
   153→registerItemCommands(program);
   154→const itemCmd = program.commands.find((cmd) => cmd.name() === "item");
   155→if (itemCmd) {
   156→  registerItemTraitCommands(itemCmd);
   157→}
   158→
   159→registerTraitCommands(program);
   160→registerValidateCommand(program);
   161→registerHelpCommand(program);
   162→registerDeriveCommand(program);
   163→registerInboxCommands(program);
   164→registerShadowCommands(program);
   165→registerLogCommand(program);
   166→registerSearchCommand(program);
   167→registerServeCommands(program);
   168→registerRalphCommand(program);
   169→registerMetaCommands(program);
   170→registerLinkCommands(program);
   171→registerModuleCommands(program);
   172→registerPlanCommands(program);
   173→registerCloneForTestingCommand(program);
   174→registerWorkflowCommand(program);
   175→registerMergeDriverCommand(program);
   176→registerExportCommand(program);
   177→registerUtilCommands(program);
   178→registerBatchCommand(program);
   179→
