      );
      console.error(chalk.gray(`Valid formats: ${VALID_FORMATS.join(", ")}`));
      process.exit(EXIT_CODES.ERROR);
    }

    // AC: @output-format-option ac-format-json, ac-format-yaml, ac-json-shorthand, ac-raw-shorthand, ac-yaml-shorthand
    // Set output format based on flags
    if (opts.format) {
