        if (existingAc.some((ac) => ac.id === acId)) {
          const itemRef = item.slugs[0] || refIndex.shortUlid(item._ulid);
          error(errors.conflict.acAlreadyExists(acId, itemRef));
          process.exit(EXIT_CODES.CONFLICT);
