      } catch (err) {
        error(errors.failures.updateAc, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec item ac remove <ref> <ac-id>
  markMutating(acCmd.command("remove <ref> <acId>"))
