          // AC: @trait-display ac-1, ac-4, ac-5 - Show inherited AC per trait in labeled sections
          if (traitsByTrait.size > 0) {
            for (const { trait, acs } of traitsByTrait.values()) {
              console.log(
                chalk.gray(`\n─── Inherited from @${trait.slug} ───`),
