                if (ac.given) console.log(`    Given: ${ac.given}`);
                if (ac.when) console.log(`    When: ${ac.when}`);
                if (ac.then) console.log(`    Then: ${ac.then}`);
              }
            }
          }
        });
      } catch (err) {
        error(errors.failures.getItem, err);
        process.exit(EXIT_CODES.ERROR);
