        const itemSlug = item.slugs[0] || refIndex.shortUlid(item._ulid);
        await commitIfShadow(ctx.shadow, "item-ac-remove", itemSlug);
        success(`Removed acceptance criterion: ${acId} from @${itemSlug}`, {
          removed: acId,
        });
      } catch (err) {
