/**
 * Reference resolution system for @references.
 *
 * Handles resolution of @slug and @ulid references to actual items,
 * with proper error handling for not-found and ambiguous cases.
 */

import type { LoadedMetaItem } from "./meta.js";
import type { LoadedPlan } from "./plans.js";
import type { AnyLoadedItem, LoadedSpecItem, LoadedTask } from "./yaml.js";

// ============================================================
// TYPES
// ============================================================

/**
 * Successful resolution result
 * AC: @agent-definitions ac-agent-3
 */
export interface ResolveSuccess {
  ok: true;
  ulid: string;
  item: AnyLoadedItem | LoadedMetaItem;
  /** How the reference was matched */
  matchType: "slug" | "ulid-full" | "ulid-prefix";
}

/**
 * Failed resolution - reference not found
 */
export interface ResolveNotFound {
  ok: false;
  error: "not_found";
  ref: string;
}

/**
 * Failed resolution - ambiguous ULID prefix
 */
export interface ResolveAmbiguous {
  ok: false;
  error: "ambiguous";
  ref: string;
  /** The matching ULIDs */
  candidates: string[];
}

/**
 * Failed resolution - duplicate slug
 */
export interface ResolveDuplicateSlug {
  ok: false;
  error: "duplicate_slug";
  ref: string;
  /** The ULIDs that share this slug */
  candidates: string[];
}

export type ResolveResult =
  | ResolveSuccess
  | ResolveNotFound
  | ResolveAmbiguous
  | ResolveDuplicateSlug;

/**
 * Validation error for a single reference
 */
export interface RefValidationError {
  /** The reference string that failed */
  ref: string;
  /** Where this reference was found */
  sourceFile?: string;
  /** The item containing this reference */
  sourceUlid?: string;
  /** The field containing this reference */
  field: string;
  /** Error type */
  error: "not_found" | "ambiguous" | "duplicate_slug";
  /** Additional context */
  message: string;
}

/**
 * Validation warning for a single reference
 */
export interface RefValidationWarning {
  /** The reference string */
  ref: string;
  /** Where this reference was found */
  sourceFile?: string;
  /** The item containing this reference */
  sourceUlid?: string;
  /** The field containing this reference */
  field: string;
  /** Warning type */
  warning: "deprecated_target";
  /** Additional context */
  message: string;
}

// ============================================================
// REFERENCE INDEX
// ============================================================

/**
 * Index for efficient reference resolution.
 * Build once when loading the spec, then resolve many times.
 * AC: @agent-definitions ac-agent-3
 */
export class ReferenceIndex {
  /** slug → ULID mapping */
  private slugIndex = new Map<string, string[]>();

  /** ULID → item mapping */
  private ulidIndex = new Map<string, AnyLoadedItem | LoadedMetaItem>();

  /** All ULIDs for prefix matching */
  private allUlids: string[] = [];

  /**
   * Build index from loaded items and meta items
   * AC: @agent-definitions ac-agent-3
   * AC: @plan-validation ac-10
   */
  constructor(
    tasks: LoadedTask[],
    items: LoadedSpecItem[],
    metaItems: LoadedMetaItem[] = [],
    plans: LoadedPlan[] = [],
  ) {
    // Index tasks
    for (const task of tasks) {
      this.indexItem(task);
    }

    // Index spec items
    for (const item of items) {
      this.indexItem(item);
    }

    // Index plans
    // AC: @plan-validation ac-10
    for (const plan of plans) {
      this.indexPlan(plan);
    }

    // Index meta items (agents, workflows, conventions, observations)
    // AC: @agent-definitions ac-agent-3
    for (const metaItem of metaItems) {
      this.indexMetaItem(metaItem);
    }

    // Sort ULIDs for consistent ordering
    this.allUlids.sort();
  }

  private indexItem(item: AnyLoadedItem): void {
    const ulid = item._ulid;

    // Index by ULID
    this.ulidIndex.set(ulid, item);
    this.allUlids.push(ulid);

    // Index by slugs
    for (const slug of item.slugs) {
      const existing = this.slugIndex.get(slug);
      if (existing) {
        existing.push(ulid);
      } else {
        this.slugIndex.set(slug, [ulid]);
      }
    }
  }

  /**
   * Index a plan
   * AC: @plan-validation ac-10
   */
  private indexPlan(plan: LoadedPlan): void {
    const ulid = plan._ulid;

    // Index by ULID
    this.ulidIndex.set(ulid, plan as unknown as AnyLoadedItem);
    this.allUlids.push(ulid);

    // Index by slugs
    for (const slug of plan.slugs) {
      const existing = this.slugIndex.get(slug);
      if (existing) {
        existing.push(ulid);
      } else {
        this.slugIndex.set(slug, [ulid]);
      }
    }
  }

  /**
   * Index a meta item (agent, workflow, convention, observation)
   * Meta items use 'id' field as their slug
   * AC: @agent-definitions ac-agent-3
   */
  private indexMetaItem(item: LoadedMetaItem): void {
    const ulid = item._ulid;

    // Index by ULID
    this.ulidIndex.set(ulid, item);
    this.allUlids.push(ulid);

    // Index by id (acts like a slug for meta items)
    const metaItem = item as { id?: string };
    if (metaItem.id) {
      const existing = this.slugIndex.get(metaItem.id);
      if (existing) {
        existing.push(ulid);
      } else {
        this.slugIndex.set(metaItem.id, [ulid]);
      }
    }
  }

  /**
   * Resolve a reference to an item.
   *
   * Resolution order:
   * 1. Exact slug match
   * 2. Full ULID match
   * 3. ULID prefix match (must be unique)
   */
  resolve(ref: string): ResolveResult {
    // Strip @ prefix if present
    const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;
    const cleanRefLower = cleanRef.toLowerCase();

    // 1. Try slug match first
    const slugMatches = this.slugIndex.get(cleanRef);
    if (slugMatches) {
      if (slugMatches.length > 1) {
        return {
          ok: false,
          error: "duplicate_slug",
          ref,
          candidates: slugMatches,
        };
      }
      const ulid = slugMatches[0];
      const item = this.ulidIndex.get(ulid)!;
      return { ok: true, ulid, item, matchType: "slug" };
    }

    // 2. Try full ULID match
    const exactMatch = this.ulidIndex.get(cleanRef.toUpperCase());
    if (exactMatch) {
      return {
        ok: true,
        ulid: exactMatch._ulid,
        item: exactMatch,
        matchType: "ulid-full",
      };
    }

    // 3. Try ULID prefix match
    const prefixMatches = this.allUlids.filter((ulid) =>
      ulid.toLowerCase().startsWith(cleanRefLower),
    );

    if (prefixMatches.length === 0) {
      return { ok: false, error: "not_found", ref };
    }

    if (prefixMatches.length > 1) {
      return {
        ok: false,
        error: "ambiguous",
        ref,
        candidates: prefixMatches,
      };
    }

    const ulid = prefixMatches[0];
    const item = this.ulidIndex.get(ulid)!;
    return { ok: true, ulid, item, matchType: "ulid-prefix" };
  }

  /**
   * Check if a slug is available (not used by any indexed item).
   * Returns true only when the slug is completely unused.
   * A slug is unavailable if it resolves to an item, is ambiguous, or is duplicated.
   */
  isSlugAvailable(slug: string): boolean {
    const result = this.resolve(slug.startsWith("@") ? slug : `@${slug}`);
    return !result.ok && result.error === "not_found";
  }

  /**
   * Get an item by exact ULID (no resolution, direct lookup)
   */
  getByUlid(ulid: string): AnyLoadedItem | LoadedMetaItem | undefined {
    return this.ulidIndex.get(ulid);
  }

  /**
   * Get the minimum unique prefix for a ULID.
   * Returns the shortest prefix that uniquely identifies this ULID
   * among all indexed items.
   *
   * @param ulid The full ULID to shorten
   * @param minLength Minimum prefix length (default 8)
   * @returns Shortest unique prefix
   */
  shortUlid(ulid: string, minLength = 8): string {
    // Start with minimum length
    let length = minLength;

    while (length < ulid.length) {
      const prefix = ulid.slice(0, length);
      const matches = this.allUlids.filter((u) =>
        u.toUpperCase().startsWith(prefix.toUpperCase()),
      );

      if (matches.length === 1) {
        return prefix;
      }

      length++;
    }

    // Return full ULID if no shorter unique prefix found
    return ulid;
  }

  /**
   * Get all indexed ULIDs
   */
  getAllUlids(): string[] {
    return [...this.allUlids];
  }

  /**
   * Get all slugs and their mappings
   */
  getAllSlugs(): Map<string, string[]> {
    return new Map(this.slugIndex);
  }

  /**
   * Check if a slug exists
   */
  hasSlug(slug: string): boolean {
    return this.slugIndex.has(slug);
  }

  /**
   * Get count of indexed items
   */
  get size(): number {
    return this.ulidIndex.size;
  }
}

// ============================================================
// VALIDATION
// ============================================================

/**
 * Fields that contain references
 * AC: @agent-definitions ac-agent-3 - added_by for agent references
 * AC: @workflow-definitions ac-workflow-3 - meta_ref for workflow references
 * AC: @traits-field ac-1 - traits field contains refs to trait-type items
 */
const REF_FIELDS = [
  "depends_on",
  "blocked_by",
  "implements",
  "relates_to",
  "tests",
  "supersedes",
  "spec_ref",
  "plan_ref", // AC: @plan-validation ac-10 - Plan reference
  "context",
  "added_by", // Agent reference
  "author", // Agent reference
  "resolved_by", // Agent reference
  "workflow_ref", // Workflow reference
  "meta_ref", // Meta reference (workflow, agent, convention)
  "traits", // Trait references (AC: @traits-field ac-1)
];

/**
 * Check if an item is deprecated
 */
function isDeprecated(item: AnyLoadedItem | LoadedMetaItem): boolean {
  const obj = item as unknown as Record<string, unknown>;

  // Check for deprecated_in field (truthy value means deprecated)
  if ("deprecated_in" in obj && obj.deprecated_in) {
    return true;
  }

  // Check for maturity: deprecated status
  if ("status" in obj && obj.status && typeof obj.status === "object") {
    const status = obj.status as Record<string, unknown>;
    if ("maturity" in status && status.maturity === "deprecated") {
      return true;
    }
  }

  // Also check top-level maturity field (some items may have it there)
  if ("maturity" in obj && obj.maturity === "deprecated") {
    return true;
  }

  return false;
}

/**
 * Extract all references from an item
 * AC: @agent-definitions ac-agent-3 - also checks nested notes for author refs
 */
function extractRefs(
  item: AnyLoadedItem,
): Array<{ field: string; ref: string }> {
  const refs: Array<{ field: string; ref: string }> = [];
  const obj = item as unknown as Record<string, unknown>;

  for (const field of REF_FIELDS) {
    const value = obj[field];

    if (typeof value === "string" && value.startsWith("@")) {
      refs.push({ field, ref: value });
    } else if (Array.isArray(value)) {
      for (const v of value) {
        if (typeof v === "string" && v.startsWith("@")) {
          refs.push({ field, ref: v });
        }
      }
    }
  }

  // Check nested notes for author references
  // AC: @agent-definitions ac-agent-3
  if ("notes" in obj && Array.isArray(obj.notes)) {
    for (const note of obj.notes) {
      if (note && typeof note === "object" && "author" in note) {
        const author = (note as { author?: string }).author;
        if (typeof author === "string" && author.startsWith("@")) {
          refs.push({ field: "notes[].author", ref: author });
        }
      }
    }
  }

  // Check nested todos for added_by references
  if ("todos" in obj && Array.isArray(obj.todos)) {
    for (const todo of obj.todos) {
      if (todo && typeof todo === "object" && "added_by" in todo) {
        const addedBy = (todo as { added_by?: string }).added_by;
        if (typeof addedBy === "string" && addedBy.startsWith("@")) {
          refs.push({ field: "todos[].added_by", ref: addedBy });
        }
      }
    }
  }

  return refs;
}

/**
 * Validation result with errors and warnings
 */
export interface RefValidationResult {
  errors: RefValidationError[];
  warnings: RefValidationWarning[];
}

/**
 * Validate all references in the spec.
 * Returns list of validation errors and warnings.
 */
export function validateRefs(
  index: ReferenceIndex,
  tasks: LoadedTask[],
  items: LoadedSpecItem[],
): RefValidationResult {
  const errors: RefValidationError[] = [];
  const warnings: RefValidationWarning[] = [];

  const allItems: AnyLoadedItem[] = [...tasks, ...items];

  for (const item of allItems) {
    const refs = extractRefs(item);
    const sourceFile = (item as LoadedTask | LoadedSpecItem)._sourceFile;

    // Track traits for duplicate detection (AC: @traits-field ac-5)
    const seenTraits = new Set<string>();

    for (const { field, ref } of refs) {
      const result = index.resolve(ref);

      if (!result.ok) {
        let message: string;

        switch (result.error) {
          case "not_found":
            message = `Reference "${ref}" not found`;
            break;
          case "ambiguous":
            message = `Reference "${ref}" is ambiguous, matches: ${result.candidates.join(", ")}`;
            break;
          case "duplicate_slug":
            message = `Slug "${ref}" maps to multiple items: ${result.candidates.join(", ")}`;
            break;
        }

        errors.push({
          ref,
          sourceFile,
          sourceUlid: item._ulid,
          field,
          error: result.error,
          message,
        });
      } else {
        // Check if resolved target is deprecated
        if (isDeprecated(result.item)) {
          const targetTitle =
            (result.item as { title?: string }).title || result.ulid;
          warnings.push({
            ref,
            sourceFile,
            sourceUlid: item._ulid,
            field,
            warning: "deprecated_target",
            message: `Reference "${ref}" points to deprecated item: ${targetTitle}`,
          });
        }

        // AC: @traits-field ac-3 - traits ref must point to trait-type item
        if (field === "traits") {
          const targetItem = result.item as { type?: string };
          if (targetItem.type !== "trait") {
            errors.push({
              ref,
              sourceFile,
              sourceUlid: item._ulid,
              field,
              error: "not_found", // Reuse error type
              message: `Trait reference "${ref}" points to non-trait item (type: ${targetItem.type || "unknown"})`,
            });
          }

          // AC: @traits-field ac-5 - warn on duplicate traits
          if (seenTraits.has(result.ulid)) {
            const targetTitle =
              (result.item as { title?: string }).title || result.ulid;
            warnings.push({
              ref,
              sourceFile,
              sourceUlid: item._ulid,
              field,
              warning: "deprecated_target", // Reuse warning type for now
              message: `Duplicate trait reference "${ref}" (${targetTitle})`,
            });
          }
          seenTraits.add(result.ulid);
        }

        // AC: @plan-validation ac-10 - plan_ref must point to a plan
        if (field === "plan_ref") {
          const targetItem = result.item as {
            derived_tasks?: unknown[];
            derived_specs?: unknown[];
          };
          // Plans have derived_tasks and derived_specs fields that tasks don't have
          const isPlan =
            "derived_tasks" in targetItem || "derived_specs" in targetItem;

          if (!isPlan) {
            warnings.push({
              ref,
              sourceFile,
              sourceUlid: item._ulid,
              field,
              warning: "deprecated_target", // Reuse warning type
              message: `Plan reference "${ref}" points to non-plan item`,
            });
          }
        }
      }
    }
  }

  return { errors, warnings };
}

/**
 * Find duplicate slugs in the index.
 * Returns map of slug → ULIDs for slugs with multiple items.
 */
export function findDuplicateSlugs(
  index: ReferenceIndex,
): Map<string, string[]> {
  const duplicates = new Map<string, string[]>();

  for (const [slug, ulids] of index.getAllSlugs()) {
    if (ulids.length > 1) {
      duplicates.set(slug, ulids);
    }
  }

  return duplicates;
}

// ============================================================
// SLUG UNIQUENESS CHECK
// ============================================================

/**
 * Result of checking slug uniqueness
 */
export interface SlugCheckSuccess {
  ok: true;
}

export interface SlugCheckConflict {
  ok: false;
  slug: string;
  existingUlid: string;
}

export type SlugCheckResult = SlugCheckSuccess | SlugCheckConflict;

/**
 * Check if proposed slugs are unique (don't conflict with existing items).
 *
 * @param index The reference index to check against
 * @param slugs Array of proposed slugs to check
 * @param excludeUlid Optional ULID to exclude from conflict check (for updates)
 * @returns Success if all slugs are available, or conflict info if one exists
 */
export function checkSlugUniqueness(
  index: ReferenceIndex,
  slugs: string[],
  excludeUlid?: string,
): SlugCheckResult {
  const allSlugs = index.getAllSlugs();

  for (const slug of slugs) {
    const existingUlids = allSlugs.get(slug);
    if (existingUlids) {
      // Filter out the item being updated (if provided)
      const conflictingUlids = excludeUlid
        ? existingUlids.filter((ulid) => ulid !== excludeUlid)
        : existingUlids;

      if (conflictingUlids.length > 0) {
        return {
          ok: false,
          slug,
          existingUlid: conflictingUlids[0],
        };
      }
    }
  }

  return { ok: true };
}

/**
 * Item index for efficient queries across spec items and tasks.
 *
 * Provides filtering by type, tags, status, and field presence.
 * Complements ReferenceIndex which handles @reference resolution.
 */

import type {
  ImplementationStatus,
  ItemType,
  Maturity,
  TaskStatus,
} from "../schema/index.js";
import { grepItem } from "../utils/grep.js";
import type { AnyLoadedItem, LoadedSpecItem, LoadedTask } from "./yaml.js";

// ============================================================
// TYPES
// ============================================================

/**
 * Filter criteria for item queries
 */
export interface ItemFilter {
  /** Filter by item type (module, feature, requirement, etc.) */
  type?: ItemType | ItemType[];
  /** Filter by tags (matches if item has ANY of these tags) */
  tags?: string[];
  /** Filter by tags (matches if item has ALL of these tags) */
  allTags?: string[];
  /** Filter by task status (for tasks only) */
  status?: TaskStatus | TaskStatus[];
  /** Filter by maturity status (for spec items) */
  maturity?: Maturity | Maturity[];
  /** Filter by implementation status (for spec items) */
  implementation?: ImplementationStatus | ImplementationStatus[];
  /** Filter items that have these fields present (non-null/undefined) */
  hasFields?: string[];
  /** Filter items that have a specific field value */
  fieldEquals?: { field: string; value: unknown }[];
  /** Text search in title */
  titleContains?: string;
  /** Include only tasks */
  tasksOnly?: boolean;
  /** Include only spec items (non-tasks) */
  specItemsOnly?: boolean;
  /** Grep-like regex search across all text content */
  grepSearch?: string;
}

/**
 * Query result with pagination info
 */
export interface QueryResult<T> {
  items: T[];
  total: number;
  offset: number;
  limit: number;
}

// ============================================================
// ITEM INDEX
// ============================================================

/**
 * Index for efficient item queries.
 * Build once when loading the spec, then query many times.
 */
export class ItemIndex {
  /** All items (tasks + spec items) */
  private allItems: AnyLoadedItem[] = [];

  /** Tasks only */
  private tasks: LoadedTask[] = [];

  /** Spec items only (non-tasks) */
  private specItems: LoadedSpecItem[] = [];

  /** Index by type */
  private typeIndex = new Map<string, AnyLoadedItem[]>();

  /** Index by tag */
  private tagIndex = new Map<string, AnyLoadedItem[]>();

  /** Index by task status */
  private statusIndex = new Map<TaskStatus, LoadedTask[]>();

  /** Index by maturity */
  private maturityIndex = new Map<Maturity, LoadedSpecItem[]>();

  /** Index by implementation status */
  private implementationIndex = new Map<
    ImplementationStatus,
    LoadedSpecItem[]
  >();

  /**
   * Build index from loaded items
   */
  constructor(tasks: LoadedTask[], items: LoadedSpecItem[]) {
    this.tasks = tasks;
    this.specItems = items;
    this.allItems = [...tasks, ...items];

    // Build indexes
    for (const item of this.allItems) {
      this.indexItem(item);
    }
  }

  private indexItem(item: AnyLoadedItem): void {
    // Index by type
    const type = item.type || "unknown";
    const typeList = this.typeIndex.get(type) || [];
    typeList.push(item);
    this.typeIndex.set(type, typeList);

    // Index by tags
    const tags = "tags" in item ? (item.tags as string[]) : [];
    for (const tag of tags) {
      const tagList = this.tagIndex.get(tag) || [];
      tagList.push(item);
      this.tagIndex.set(tag, tagList);
    }

    // Index tasks by status
    if ("status" in item && typeof item.status === "string") {
      const task = item as LoadedTask;
      const statusList = this.statusIndex.get(task.status) || [];
      statusList.push(task);
      this.statusIndex.set(task.status, statusList);
    }

    // Index spec items by maturity/implementation
    if (
      "status" in item &&
      typeof item.status === "object" &&
      item.status !== null
    ) {
      const specItem = item as LoadedSpecItem;
      const status = specItem.status as {
        maturity?: Maturity;
        implementation?: ImplementationStatus;
      };

      if (status.maturity) {
        const maturityList = this.maturityIndex.get(status.maturity) || [];
        maturityList.push(specItem);
        this.maturityIndex.set(status.maturity, maturityList);
      }

      if (status.implementation) {
        const implList =
          this.implementationIndex.get(status.implementation) || [];
        implList.push(specItem);
        this.implementationIndex.set(status.implementation, implList);
      }
    }
  }

  /**
   * Query items with filters
   */
  query(filter: ItemFilter = {}): AnyLoadedItem[] {
    let results: AnyLoadedItem[];

    // Start with appropriate base set
    if (filter.tasksOnly) {
      results = [...this.tasks];
    } else if (filter.specItemsOnly) {
      results = [...this.specItems];
    } else {
      results = [...this.allItems];
    }

    // Apply type filter
    if (filter.type) {
      const types = Array.isArray(filter.type) ? filter.type : [filter.type];
      results = results.filter((item) => types.includes(item.type as ItemType));
    }

    // Apply tag filter (ANY)
    if (filter.tags && filter.tags.length > 0) {
      results = results.filter((item) => {
        const itemTags = "tags" in item ? (item.tags as string[]) : [];
        return filter.tags?.some((tag) => itemTags.includes(tag));
      });
    }

    // Apply tag filter (ALL)
    if (filter.allTags && filter.allTags.length > 0) {
      results = results.filter((item) => {
        const itemTags = "tags" in item ? (item.tags as string[]) : [];
        return filter.allTags?.every((tag) => itemTags.includes(tag));
      });
    }

    // Apply task status filter
    if (filter.status) {
      const statuses = Array.isArray(filter.status)
        ? filter.status
        : [filter.status];
      results = results.filter((item) => {
        if (!("status" in item) || typeof item.status !== "string")
          return false;
        return statuses.includes(item.status as TaskStatus);
      });
    }

    // Apply maturity filter
    if (filter.maturity) {
      const maturities = Array.isArray(filter.maturity)
        ? filter.maturity
        : [filter.maturity];
      results = results.filter((item) => {
        if (
          !("status" in item) ||
          typeof item.status !== "object" ||
          !item.status
        )
          return false;
        const status = item.status as { maturity?: Maturity };
        return status.maturity && maturities.includes(status.maturity);
      });
    }

    // Apply implementation filter
    if (filter.implementation) {
      const impls = Array.isArray(filter.implementation)
        ? filter.implementation
        : [filter.implementation];
      results = results.filter((item) => {
        if (
          !("status" in item) ||
          typeof item.status !== "object" ||
          !item.status
        )
          return false;
        const status = item.status as { implementation?: ImplementationStatus };
        return status.implementation && impls.includes(status.implementation);
      });
    }

    // Apply has-fields filter
    if (filter.hasFields && filter.hasFields.length > 0) {
      results = results.filter((item) => {
        const obj = item as unknown as Record<string, unknown>;
        return filter.hasFields?.every((field) => {
          const value = getNestedField(obj, field);
          return value !== undefined && value !== null;
        });
      });
    }

    // Apply field-equals filter
    if (filter.fieldEquals && filter.fieldEquals.length > 0) {
      results = results.filter((item) => {
        const obj = item as unknown as Record<string, unknown>;
        return filter.fieldEquals?.every(({ field, value }) => {
          const itemValue = getNestedField(obj, field);
          return itemValue === value;
        });
      });
    }

    // Apply title search
    if (filter.titleContains) {
      const search = filter.titleContains.toLowerCase();
      results = results.filter((item) =>
        item.title.toLowerCase().includes(search),
      );
    }

    // Apply grep search (regex across all text content)
    if (filter.grepSearch) {
      results = results.filter((item) => {
        const match = grepItem(
          item as unknown as Record<string, unknown>,
          filter.grepSearch!,
        );
        return match !== null;
      });
    }

    return results;
  }

  /**
   * Query with pagination
   */
  queryPaginated(
    filter: ItemFilter = {},
    offset = 0,
    limit = 50,
  ): QueryResult<AnyLoadedItem> {
    const allResults = this.query(filter);
    const items = allResults.slice(offset, offset + limit);

    return {
      items,
      total: allResults.length,
      offset,
      limit,
    };
  }

  /**
   * Get items by type
   */
  getByType(type: ItemType): AnyLoadedItem[] {
    return this.typeIndex.get(type) || [];
  }

  /**
   * Get items by tag
   */
  getByTag(tag: string): AnyLoadedItem[] {
    return this.tagIndex.get(tag) || [];
  }

  /**
   * Get tasks by status
   */
  getTasksByStatus(status: TaskStatus): LoadedTask[] {
    return this.statusIndex.get(status) || [];
  }

  /**
   * Get spec items by maturity
   */
  getByMaturity(maturity: Maturity): LoadedSpecItem[] {
    return this.maturityIndex.get(maturity) || [];
  }

  /**
   * Get spec items by implementation status
   */
  getByImplementation(impl: ImplementationStatus): LoadedSpecItem[] {
    return this.implementationIndex.get(impl) || [];
  }

  /**
   * Get all unique types in the index
   */
  getTypes(): string[] {
    return [...this.typeIndex.keys()].sort();
  }

  /**
   * Get all unique tags in the index
   */
  getTags(): string[] {
    return [...this.tagIndex.keys()].sort();
  }

  /**
   * Get count by type
   */
  getTypeCounts(): Map<string, number> {
    const counts = new Map<string, number>();
    for (const [type, items] of this.typeIndex) {
      counts.set(type, items.length);
    }
    return counts;
  }

  /**
   * Get count by tag
   */
  getTagCounts(): Map<string, number> {
    const counts = new Map<string, number>();
    for (const [tag, items] of this.tagIndex) {
      counts.set(tag, items.length);
    }
    return counts;
  }

  /**
   * Get total item count
   */
  get size(): number {
    return this.allItems.length;
  }

  /**
   * Get task count
   */
  get taskCount(): number {
    return this.tasks.length;
  }

  /**
   * Get spec item count
   */
  get specItemCount(): number {
    return this.specItems.length;
  }
}

