file.content:
/**
 * Meta manifest loading and operations.
 *
 * The meta manifest (kynetic.meta.yaml) contains process definitions:
 * - Agents: roles, capabilities, conventions
 * - Workflows: structured processes with steps
 * - Conventions: project rules and standards
 * - Observations: feedback about processes
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import { ulid } from "ulid";
import {
  type Agent,
  AgentSchema,
  type Convention,
  ConventionSchema,
  getMetaItemType,
  type MetaItem,
  type MetaManifest,
  MetaManifestSchema,
  type Observation,
  ObservationSchema,
  type ObservationType,
  type SessionContext,
  SessionContextSchema,
  type Workflow,
  type WorkflowRun,
  type WorkflowRunsFile,
  WorkflowRunsFileSchema,
  WorkflowSchema,
} from "../schema/index.js";
import type { KspecContext } from "./yaml.js";
import {
  expandIncludePattern,
  getAuthor,
  readYamlFile,
  writeYamlFilePreserveFormat,
} from "./yaml.js";

/**
 * Loaded agent with runtime metadata
 */
export interface LoadedAgent extends Agent {
  _sourceFile?: string;
}

/**
 * Loaded workflow with runtime metadata
 */
export interface LoadedWorkflow extends Workflow {
  _sourceFile?: string;
}

/**
 * Loaded convention with runtime metadata
 */
export interface LoadedConvention extends Convention {
  _sourceFile?: string;
}

/**
 * Loaded observation with runtime metadata
 */
export interface LoadedObservation extends Observation {
  _sourceFile?: string;
}

/**
 * Any loaded meta item
 */
export type LoadedMetaItem =
  | LoadedAgent
  | LoadedWorkflow
  | LoadedConvention
  | LoadedObservation;

/**
 * Meta context containing all loaded meta items
 */
export interface MetaContext {
  manifest: MetaManifest | null;
  manifestPath: string | null;
  agents: LoadedAgent[];
  workflows: LoadedWorkflow[];
  conventions: LoadedConvention[];
  observations: LoadedObservation[];
}

/**
 * Find the meta manifest file.
 *
 * Discovery algorithm:
 * 1. Check for explicit name: kynetic.meta.yaml (backward compat)
 * 2. If not found, scan directory for *.meta.yaml files
 * 3. For each candidate, validate it contains a 'kynetic_meta:' version field
 * 4. Return first valid match (alphabetically after explicit name)
 *
 * AC: @meta-manifest-discovery ac-1, ac-2, ac-3
 */
export async function findMetaManifest(
  specDir: string,
): Promise<string | null> {
  // AC: @meta-manifest-discovery ac-1, ac-3 - explicit name has priority
  const priorityPath = path.join(specDir, "kynetic.meta.yaml");
  try {
    await fs.access(priorityPath);
    return priorityPath;
  } catch {
    // Continue to glob fallback
  }

  // AC: @meta-manifest-discovery ac-2, ac-3 - glob fallback with validation
  try {
    const entries = await fs.readdir(specDir);
    // AC: @meta-manifest-discovery ac-3 - alphabetical order
    const candidates = entries
      .filter((f) => f.endsWith(".meta.yaml"))
      .sort();

    for (const candidate of candidates) {
      const filePath = path.join(specDir, candidate);
      try {
        const raw = await readYamlFile<unknown>(filePath);
        // AC: @meta-manifest-discovery ac-2 - validate kynetic_meta version field
        if (raw && typeof raw === "object" && "kynetic_meta" in raw) {
          return filePath;
        }
      } catch {
        // Skip invalid files
      }
    }
  } catch {
    // Directory read failed
  }

  return null;
}

/**
 * Get the base name (slug) from a manifest path.
 * E.g., "kynetic.yaml" -> "kynetic", "myproject.spec.yaml" -> "myproject"
 */
function getManifestBaseName(manifestPath: string | null): string {
  if (!manifestPath) return "kynetic";
  const fileName = path.basename(manifestPath);
  // Remove .yaml extension
  let baseName = fileName.replace(/\.yaml$/, "");
  // Remove .spec suffix if present
  baseName = baseName.replace(/\.spec$/, "");
  return baseName || "kynetic";
}

/**
 * Get the meta manifest file path.
 * Derives from main manifest name (e.g., myproject.yaml -> myproject.meta.yaml)
 * Returns path even if file doesn't exist yet.
 */
export function getMetaManifestPath(ctx: KspecContext): string {
  const baseName = getManifestBaseName(ctx.manifestPath);
  return path.join(ctx.specDir, `${baseName}.meta.yaml`);
}

/**
 * Load meta items from a single file.
 */
async function loadMetaFile(filePath: string): Promise<{
  agents: LoadedAgent[];
  workflows: LoadedWorkflow[];
  conventions: LoadedConvention[];
  observations: LoadedObservation[];
}> {
  const result: {
    agents: LoadedAgent[];
    workflows: LoadedWorkflow[];
    conventions: LoadedConvention[];
    observations: LoadedObservation[];
  } = {
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
  };

  try {
    const raw = await readYamlFile<unknown>(filePath);
    if (!raw || typeof raw !== "object") {
      return result;
    }

    const obj = raw as Record<string, unknown>;

    // Parse agents
    if (Array.isArray(obj.agents)) {
      for (const agent of obj.agents) {
        const parsed = AgentSchema.safeParse(agent);
        if (parsed.success) {
          result.agents.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse workflows
    if (Array.isArray(obj.workflows)) {
      for (const workflow of obj.workflows) {
        const parsed = WorkflowSchema.safeParse(workflow);
        if (parsed.success) {
          result.workflows.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse conventions
    if (Array.isArray(obj.conventions)) {
      for (const convention of obj.conventions) {
        const parsed = ConventionSchema.safeParse(convention);
        if (parsed.success) {
          result.conventions.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse observations
    if (Array.isArray(obj.observations)) {
      for (const observation of obj.observations) {
        const parsed = ObservationSchema.safeParse(observation);
        if (parsed.success) {
          result.observations.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }
  } catch {
    // File doesn't exist or parse error
  }

  return result;
}

/**
 * Load the meta context from a kspec context.
 * Loads meta manifest and follows includes.
 */
export async function loadMetaContext(ctx: KspecContext): Promise<MetaContext> {
  const result: MetaContext = {
    manifest: null,
    manifestPath: null,
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
  };

  const manifestPath = await findMetaManifest(ctx.specDir);
  if (!manifestPath) {
    return result;
  }

  result.manifestPath = manifestPath;

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      // Invalid manifest, but we can still try to extract items
      const items = await loadMetaFile(manifestPath);
      result.agents.push(...items.agents);
      result.workflows.push(...items.workflows);
      result.conventions.push(...items.conventions);
      result.observations.push(...items.observations);
      return result;
    }

    result.manifest = parsed.data;

    // Load items from manifest
    const manifestItems = await loadMetaFile(manifestPath);
    result.agents.push(...manifestItems.agents);
    result.workflows.push(...manifestItems.workflows);
    result.conventions.push(...manifestItems.conventions);
    result.observations.push(...manifestItems.observations);

    // Process includes
    const includes = parsed.data.includes || [];
    const manifestDir = path.dirname(manifestPath);

    for (const include of includes) {
      const expandedPaths = await expandIncludePattern(include, manifestDir);

      for (const filePath of expandedPaths) {
        const items = await loadMetaFile(filePath);
        result.agents.push(...items.agents);
        result.workflows.push(...items.workflows);
        result.conventions.push(...items.conventions);
        result.observations.push(...items.observations);
      }
    }
  } catch {
    // Manifest exists but may be invalid
  }

  return result;
}

/**
 * Get meta stats summary
 */
export function getMetaStats(meta: MetaContext): {
  agents: number;
  workflows: number;
  conventions: number;
  observations: number;
  unresolvedObservations: number;
} {
  return {
    agents: meta.agents.length,
    workflows: meta.workflows.length,
    conventions: meta.conventions.length,
    observations: meta.observations.length,
    unresolvedObservations: meta.observations.filter((o) => !o.resolved).length,
  };
}

/**
 * Find a meta item by reference (ULID, short ULID, or id)
 */
export function findMetaItemByRef(
  meta: MetaContext,
  ref: string,
): LoadedMetaItem | undefined {
  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;

  // Search all item types
  const allItems: LoadedMetaItem[] = [
    ...meta.agents,
    ...meta.workflows,
    ...meta.conventions,
    ...meta.observations,
  ];

  for (const item of allItems) {
    // Match full ULID
    if (item._ulid === cleanRef) return item;

    // Match short ULID (prefix)
    if (item._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()))
      return item;

    // Match by id (for agents and workflows)
    if ("id" in item && item.id === cleanRef) return item;

    // Match by domain (for conventions)
    if ("domain" in item && item.domain === cleanRef) return item;
  }

  return undefined;
}

/**
 * Determine if an item is a meta item type
 */
export function isMetaItemType(type: string): boolean {
  return ["agent", "workflow", "convention", "observation"].includes(type);
}

// ============================================================
// META ITEM CRUD
// ============================================================

/**
 * Save the entire meta manifest to file
 */
async function saveMetaManifest(
  manifestPath: string,
  manifest: MetaManifest,
): Promise<void> {
  await writeYamlFilePreserveFormat(manifestPath, manifest);
}

/**
 * Strip runtime metadata before serialization
 */
function stripMetaMetadata<T extends LoadedMetaItem>(
  item: T,
): Omit<T, "_sourceFile"> {
  const { _sourceFile, ...cleanItem } = item;
  return cleanItem as Omit<T, "_sourceFile">;
}

/**
 * Create a new observation
 */
export function createObservation(
  type: ObservationType,
  content: string,
  options: {
    workflow_ref?: string;
    author?: string;
  } = {},
): Observation {
  return {
    _ulid: ulid(),
    type,
    content,
    workflow_ref: options.workflow_ref,
    created_at: new Date().toISOString(),
    author: options.author ?? getAuthor(),
    resolved: false,
    resolution: null,
  };
}

/**
 * Save an observation to the meta manifest
 */
export async function saveObservation(
  ctx: KspecContext,
  observation: LoadedObservation,
): Promise<void> {
  const manifestPath = getMetaManifestPath(ctx);

  // Ensure directory exists
  const dir = path.dirname(manifestPath);
  await fs.mkdir(dir, { recursive: true });

  // Load existing manifest
  let manifest: MetaManifest = {
    kynetic_meta: "1.0",
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
    includes: [],
  };

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (parsed.success) {
      manifest = parsed.data;
    }
  } catch {
    // File doesn't exist, use defaults
  }

  // Strip runtime metadata
  const cleanObs = stripMetaMetadata(observation);

  // Update or add
  const existingIndex = manifest.observations.findIndex(
    (o) => o._ulid === observation._ulid,
  );
  if (existingIndex >= 0) {
    manifest.observations[existingIndex] = cleanObs as Observation;
  } else {
    manifest.observations.push(cleanObs as Observation);
  }

  await saveMetaManifest(manifestPath, manifest);
}

/**
 * Delete an observation from the meta manifest
 */
export async function deleteObservation(
  ctx: KspecContext,
  ulid: string,
): Promise<boolean> {
  const manifestPath = getMetaManifestPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      return false;
    }

    const manifest = parsed.data;
    const index = manifest.observations.findIndex((o) => o._ulid === ulid);
    if (index < 0) {
      return false;
    }

    manifest.observations.splice(index, 1);
    await saveMetaManifest(manifestPath, manifest);
    return true;
  } catch {
    return false;
  }
}

// Re-export the getMetaItemType function
export { getMetaItemType };
export type { Agent, Workflow, Convention, Observation, MetaItem };

// ============================================================
// GENERIC META ITEM CRUD
// ============================================================

/**
 * Save any meta item (agent, workflow, convention) to the manifest
 */
export async function saveMetaItem(
  ctx: KspecContext,
  item: LoadedMetaItem,
  itemType: "agent" | "workflow" | "convention",
): Promise<void> {
  const manifestPath = getMetaManifestPath(ctx);

  // Ensure directory exists
  const dir = path.dirname(manifestPath);
  await fs.mkdir(dir, { recursive: true });

  // Load existing manifest
  let manifest: MetaManifest = {
    kynetic_meta: "1.0",
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
    includes: [],
  };

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (parsed.success) {
      manifest = parsed.data;
    }
  } catch {
    // File doesn't exist, use defaults
  }

  // Strip runtime metadata
  const cleanItem = stripMetaMetadata(item);

  // Get the appropriate array
  const getArray = () => {
    switch (itemType) {
      case "agent":
        return manifest.agents;
      case "workflow":
        return manifest.workflows;
      case "convention":
        return manifest.conventions;
    }
  };

  const array = getArray();

  // Update or add
  const existingIndex = array.findIndex((i) => i._ulid === item._ulid);
  if (existingIndex >= 0) {
    (array as unknown[])[existingIndex] = cleanItem;
  } else {
    (array as unknown[]).push(cleanItem);
  }

  await saveMetaManifest(manifestPath, manifest);
}

/**
 * Delete any meta item from the manifest
 */
export async function deleteMetaItem(
  ctx: KspecContext,
  itemUlid: string,
  itemType: "agent" | "workflow" | "convention" | "observation",
): Promise<boolean> {
  const manifestPath = getMetaManifestPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      return false;
    }

    const manifest = parsed.data;

    const getArray = () => {
      switch (itemType) {
        case "agent":
          return manifest.agents;
        case "workflow":
          return manifest.workflows;
        case "convention":
          return manifest.conventions;
        case "observation":
          return manifest.observations;
      }
    };

    const array = getArray();
    const index = array.findIndex((i) => i._ulid === itemUlid);
    if (index < 0) {
      return false;
    }

    array.splice(index, 1);
    await saveMetaManifest(manifestPath, manifest);
    return true;
  } catch {
    return false;
  }
}

// ============================================================
// SESSION CONTEXT
// ============================================================

/**
 * Get the session context file path
 */
export function getSessionContextPath(ctx: KspecContext): string {
  return path.join(ctx.specDir, ".kspec-session");
}

/**
 * Load session context (or return empty context if not exists)
 */
export async function loadSessionContext(
  ctx: KspecContext,
): Promise<SessionContext> {
  const contextPath = getSessionContextPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(contextPath);
    if (!raw || typeof raw !== "object") {
      return {
        focus: null,
        threads: [],
        open_questions: [],
        updated_at: new Date().toISOString(),
      };
    }

    // Validate and parse using schema
    const result = SessionContextSchema.safeParse(raw);
    if (result.success) {
      return result.data;
    }

    // If validation fails, return empty context
    return {
      focus: null,
      threads: [],
      open_questions: [],
      updated_at: new Date().toISOString(),
    };
  } catch {
    return {
      focus: null,
      threads: [],
      open_questions: [],
      updated_at: new Date().toISOString(),
    };
  }
}

/**
 * Save session context
 */
export async function saveSessionContext(
  ctx: KspecContext,
  context: SessionContext,
): Promise<void> {
  const contextPath = getSessionContextPath(ctx);

  // Update timestamp
  context.updated_at = new Date().toISOString();

  await writeYamlFilePreserveFormat(contextPath, context);
}

// ============================================================
// WORKFLOW RUNS
// ============================================================

/**
 * Get the workflow runs file path.
 * Derives from main manifest name (e.g., myproject.yaml -> myproject.runs.yaml)
 */
export function getWorkflowRunsPath(ctx: KspecContext): string {
  const baseName = getManifestBaseName(ctx.manifestPath);
  return path.join(ctx.specDir, `${baseName}.runs.yaml`);
}

/**
 * Load workflow runs from file
 */
export async function loadWorkflowRuns(
  ctx: KspecContext,
): Promise<WorkflowRun[]> {
  const runsPath = getWorkflowRunsPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(runsPath);
    const parsed = WorkflowRunsFileSchema.safeParse(raw);

    if (!parsed.success) {
      return [];
    }

    return parsed.data.runs;
  } catch {
    // File doesn't exist
    return [];
  }
}

/**
 * Save a workflow run (create or update)
 */
export async function saveWorkflowRun(
  ctx: KspecContext,
  run: WorkflowRun,
): Promise<void> {
  const runsPath = getWorkflowRunsPath(ctx);

  // Load existing runs
  const runs = await loadWorkflowRuns(ctx);

  // Update or add
  const existingIndex = runs.findIndex((r) => r._ulid === run._ulid);
  if (existingIndex >= 0) {
    runs[existingIndex] = run;
  } else {
    runs.push(run);
  }

  // Save back
  const runsFile: WorkflowRunsFile = {
    kynetic_runs: "1.0",
    runs,
  };

  await writeYamlFilePreserveFormat(runsPath, runsFile);
}

/**
 * Update an existing workflow run
 */
export async function updateWorkflowRun(
  ctx: KspecContext,
  run: WorkflowRun,
): Promise<void> {
  await saveWorkflowRun(ctx, run);
}

/**
 * Find a workflow run by reference (ULID or ULID prefix)
 */
export async function findWorkflowRunByRef(
  ctx: KspecContext,
  ref: string,
): Promise<WorkflowRun | undefined> {
  const runs = await loadWorkflowRuns(ctx);
  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;

  return runs.find(
    (r) =>
      r._ulid === cleanRef ||
      r._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()),
  );
}

/**
 * Find active workflow runs
 */
export async function findActiveRuns(
  ctx: KspecContext,
): Promise<WorkflowRun[]> {
  const runs = await loadWorkflowRuns(ctx);
  return runs.filter((r) => r.status === "active");
}

/**
 * Delete workflow runs by ULIDs
 * AC: @workflow-prune ac-1, ac-2, ac-3, ac-4
 */
export async function deleteWorkflowRuns(
  ctx: KspecContext,
  ulidsToDelete: string[],
): Promise<void> {
  const runsPath = getWorkflowRunsPath(ctx);
  const runs = await loadWorkflowRuns(ctx);

  // Filter out runs to delete
  const remainingRuns = runs.filter((r) => !ulidsToDelete.includes(r._ulid));

  // Save back
  const runsFile: WorkflowRunsFile = {
    kynetic_runs: "1.0",
    runs: remainingRuns,
  };

  await writeYamlFilePreserveFormat(runsPath, runsFile);
}

import chalk from "chalk";
import { stringify as yamlStringify } from "yaml";
import type { ReferenceIndex } from "../parser/index.js";
import type { Note, Task, TaskStatus } from "../schema/index.js";
import { fieldLabels, sectionHeaders, summaries } from "../strings/labels.js";
import { formatMatchedFields, grepItem } from "../utils/grep.js";

/**
 * Check if a note has been superseded by another note.
 * A note is superseded if its ULID appears in any other note's `supersedes` field.
 */
export function isNoteSuperseded(note: Note, allNotes: Note[]): boolean {
  return allNotes.some((n) => n.supersedes === note._ulid);
}

/**
 * Filter notes to exclude superseded ones.
 * Returns only notes that have not been superseded.
 */
export function filterSupersededNotes(notes: Note[]): Note[] {
  return notes.filter((note) => !isNoteSuperseded(note, notes));
}

/**
 * Annotate notes with superseded status for JSON output.
 * Adds a computed `superseded` field to each note.
 */
export function annotateNotesWithSuperseded(
  notes: Note[],
): Array<Note & { superseded: boolean }> {
  return notes.map((note) => ({
    ...note,
    superseded: isNoteSuperseded(note, notes),
  }));
}

/**
 * Output options
 */
export interface OutputOptions {
  json?: boolean;
}

/**
 * Output format types
 * AC: @output-format-option
 */
export type OutputFormat = "text" | "json" | "yaml";

/**
 * Valid format values for --format option
 */
export const VALID_FORMATS = ["json", "yaml"] as const;

/**
 * Global output format (set by --json, --yaml, --raw, or --format flags)
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
let globalOutputFormat: OutputFormat = "text";

export function setOutputFormat(format: OutputFormat): void {
  globalOutputFormat = format;
}

export function getOutputFormat(): OutputFormat {
  return globalOutputFormat;
}

/**
 * Set JSON mode (for backward compatibility)
 * AC: @output-format-option ac-json-shorthand
 */
export function setJsonMode(enabled: boolean): void {
  if (enabled) {
    globalOutputFormat = "json";
  } else if (globalOutputFormat === "json") {
    globalOutputFormat = "text";
  }
}

/**
 * Check if JSON mode is active
 * AC: @output-format-option ac-json-shorthand
 */
export function isJsonMode(): boolean {
  return globalOutputFormat === "json";
}

/**
 * Set YAML mode
 * AC: @output-format-option ac-format-yaml, ac-yaml-shorthand
 */
export function setYamlMode(enabled: boolean): void {
  if (enabled) {
    globalOutputFormat = "yaml";
  } else if (globalOutputFormat === "yaml") {
    globalOutputFormat = "text";
  }
}

/**
 * Check if YAML mode is active
 * AC: @output-format-option ac-format-yaml
 */
export function isYamlMode(): boolean {
  return globalOutputFormat === "yaml";
}

/**
 * Check if any structured output mode is active (JSON or YAML)
 * AC: @output-format-option ac-yaml-no-ansi, ac-yaml-references
 */
export function isStructuredMode(): boolean {
  return globalOutputFormat === "json" || globalOutputFormat === "yaml";
}

/**
 * Global verbose mode (set by --verbose flag)
 */
let globalVerboseMode = false;

export function setVerboseMode(enabled: boolean): void {
  globalVerboseMode = enabled;
}

export function getVerboseMode(): boolean {
  return globalVerboseMode;
}

/**
 * Output data - JSON/YAML if structured mode, otherwise formatted
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
export function output(data: unknown, formatter?: () => void): void {
  if (globalOutputFormat === "json") {
    console.log(JSON.stringify(data, null, 2));
  } else if (globalOutputFormat === "yaml") {
    console.log(yamlStringify(data, { indent: 2 }));
  } else if (formatter) {
    formatter();
  } else {
    console.log(data);
  }
}

/**
 * Output success message
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
export function success(message: string, data?: Record<string, unknown>): void {
  if (globalOutputFormat === "json") {
    console.log(JSON.stringify({ success: true, message, ...data }));
  } else if (globalOutputFormat === "yaml") {
    console.log(yamlStringify({ success: true, message, ...data }, { indent: 2 }));
  } else {
    console.log(chalk.green("OK"), message);
  }
}

/**
 * Output error message
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
export function error(message: string, details?: unknown): void {
  if (globalOutputFormat === "json") {
    console.error(JSON.stringify({ success: false, error: message, details }));
  } else if (globalOutputFormat === "yaml") {
    console.error(yamlStringify({ success: false, error: message, details }, { indent: 2 }));
  } else {
    console.error(chalk.red("✗"), message);
    if (details) {
      console.error(chalk.gray(String(details)));
      // Show suggestion if it's a ShadowError with a suggestion
      if (details && typeof details === "object" && "suggestion" in details) {
        const suggestion = (details as { suggestion?: string }).suggestion;
        if (suggestion) {
          console.error(chalk.yellow("  Suggestion:"), suggestion);
        }
      }
    }
  }
}

/**
 * Output warning message
 * AC: @output-format-option ac-yaml-no-ansi
 */
export function warn(message: string): void {
  if (isStructuredMode()) {
    // Warnings are suppressed in structured output modes
  } else {
    console.warn(chalk.yellow("⚠"), message);
  }
}

/**
 * Output info message
 * AC: @output-format-option ac-yaml-no-ansi
 */
export function info(message: string): void {
  if (isStructuredMode()) {
    // Info messages suppressed in structured output modes
  } else {
    console.log(chalk.blue("ℹ"), message);
  }
}

/**
 * Get color for task status
 */
function statusColor(status: TaskStatus): (text: string) => string {
  switch (status) {
    case "pending":
      return (t: string) => chalk.gray(t);
    case "in_progress":
      return (t: string) => chalk.blue(t);
    case "blocked":
      return (t: string) => chalk.red(t);
    case "completed":
      return (t: string) => chalk.green(t);
    case "cancelled":
      return (t: string) => chalk.strikethrough.gray(t);
    default:
      return (t: string) => chalk.white(t);
  }
}

/**
 * Format a task reference (short ULID + slug if available)
 * @param task The task to format
 * @param index Optional ReferenceIndex for dynamic short ULID computation
 */
export function formatTaskRef(task: Task, index?: ReferenceIndex): string {
  const shortId = index ? index.shortUlid(task._ulid) : task._ulid.slice(0, 8);
  if (task.slugs.length > 0) {
    return `${shortId} (${task.slugs[0]})`;
  }
  return shortId;
}

/**
 * Format task for display
 */
export function formatTask(
  task: Task,
  verbose = false,
  index?: ReferenceIndex,
  full = false,
): string {
  const ref = formatTaskRef(task, index);
  const status = statusColor(task.status)(`[${task.status}]`);
  const priority =
    task.priority <= 2
      ? chalk.red(`P${task.priority}`)
      : chalk.gray(`P${task.priority}`);

  let line = `${ref} ${status} ${priority} ${task.title}`;

  if (verbose && !full) {
    // AC: @task-list-verbose ac-2 - Single verbose (-v) shows current behavior
    if (task.spec_ref) {
      line += chalk.gray(` (spec: ${task.spec_ref})`);
    }
    if (task.depends_on.length > 0) {
      line += chalk.gray(` deps: [${task.depends_on.join(", ")}]`);
    }
    if (task.tags.length > 0) {
      line += chalk.cyan(` #${task.tags.join(" #")}`);
    }
  }

  return line;
}

/**
 * Get first line of text, truncated to max length
 */
function getFirstLine(
  text: string | undefined,
  maxLength: number = 70,
): string | undefined {
  if (!text) return undefined;
  const firstLine = text.split("\n")[0].trim();
  if (firstLine.length <= maxLength) return firstLine;
  return `${firstLine.slice(0, maxLength - 3)}...`;
}

/**
 * Format full mode context for a task (AC-1, AC-3, AC-5)
 */
function formatFullModeContext(task: Task, index?: ReferenceIndex): void {
  const indent = "    ";

  // Show timestamps (AC-1)
  console.log(chalk.gray(`${indent}Created: ${task.created_at}`));
  if (task.started_at) {
    console.log(chalk.gray(`${indent}Started: ${task.started_at}`));
  }
  if (task.completed_at) {
    console.log(chalk.gray(`${indent}Completed: ${task.completed_at}`));
  }

  // Show notes count and most recent note (AC-1, AC-3)
  if (task.notes && task.notes.length > 0) {
    const mostRecent = task.notes[task.notes.length - 1];
    const preview = getFirstLine(mostRecent.content, 50);
    console.log(
      chalk.gray(`${indent}Notes: ${task.notes.length} (latest: "${preview}")`),
    );
  }

  // Show pending todos count (AC-1, AC-3)
  if (task.todos && task.todos.length > 0) {
    const pendingCount = task.todos.filter((t) => !t.done).length;
    if (pendingCount > 0) {
      console.log(chalk.gray(`${indent}Pending todos: ${pendingCount}`));
    }
  }

  // Show spec context (AC-5)
  if (task.spec_ref && index) {
    const result = index.resolve(task.spec_ref);
    if (result.ok) {
      const spec = result.item;
      const specName =
        "title" in spec
          ? spec.title
          : "name" in spec
            ? spec.name
            : "id" in spec
              ? spec.id
              : task.spec_ref;
      console.log(chalk.gray(`${indent}Spec: ${task.spec_ref}`));
      console.log(chalk.cyan(`${indent}  ${specName}`));

      // Show spec description if available
      if ("description" in spec && spec.description) {
        const descPreview = getFirstLine(spec.description as string, 70);
        console.log(chalk.gray(`${indent}  ${descPreview}`));
      }

      // Show acceptance criteria if available
      if (
        "acceptance_criteria" in spec &&
        Array.isArray(spec.acceptance_criteria)
      ) {
        const ac = spec.acceptance_criteria;
        if (ac.length > 0) {
          console.log(
            chalk.gray(`${indent}  Acceptance Criteria: ${ac.length}`),
          );
          // Show first AC as preview
          const firstAC = ac[0];
          if (
            typeof firstAC === "object" &&
            firstAC !== null &&
            "id" in firstAC
          ) {
            console.log(
              chalk.gray(`${indent}    [${firstAC.id}] ${firstAC.then}`),
            );
          }
        }
      }
    }
  }

  // Show tags and dependencies if present
  if (task.tags && task.tags.length > 0) {
    console.log(chalk.gray(`${indent}Tags: ${task.tags.join(", ")}`));
  }
  if (task.depends_on && task.depends_on.length > 0) {
    console.log(
      chalk.gray(`${indent}Depends on: ${task.depends_on.join(", ")}`),
    );
  }
}

/**
 * Format automation status as a colored label
 * AC: @task-automation-eligibility ac-14
 */
function formatAutomationStatus(automation: string | undefined): string {
  if (!automation) {
    return chalk.gray("[unassessed]");
  }
  switch (automation) {
    case "eligible":
      return chalk.green("[eligible]");
    case "needs_review":
      return chalk.yellow("[needs_review]");
    case "manual_only":
      return chalk.red("[manual_only]");
    default:
      return chalk.gray(`[${automation}]`);
  }
}

/**
 * Format a list of tasks with automation status
 * AC: @task-automation-eligibility ac-14
 */
export function formatTaskListWithAutomation(
  tasks: Task[],
  verbose = false,
  index?: ReferenceIndex,
  grepPattern?: string,
  full = false,
): void {
  if (tasks.length === 0) {
    console.log(summaries.noTasks);
    return;
  }

  for (const task of tasks) {
    const ref = formatTaskRef(task, index);
    const status = statusColor(task.status)(`[${task.status}]`);
    const priority =
      task.priority <= 2
        ? chalk.red(`P${task.priority}`)
        : chalk.gray(`P${task.priority}`);
    const automationLabel = formatAutomationStatus(task.automation);

    let line = `${ref} ${status} ${priority} ${automationLabel} ${task.title}`;

    if (verbose && !full) {
      if (task.spec_ref) {
        line += chalk.gray(` (spec: ${task.spec_ref})`);
      }
      if (task.depends_on.length > 0) {
        line += chalk.gray(` deps: [${task.depends_on.join(", ")}]`);
      }
      if (task.tags.length > 0) {
        line += chalk.cyan(` #${task.tags.join(" #")}`);
      }
    }

    console.log(line);

    // Show matched fields if grep pattern provided
    if (grepPattern) {
      const match = grepItem(
        task as unknown as Record<string, unknown>,
        grepPattern,
      );
      if (match && match.matchedFields.length > 0) {
        console.log(
          chalk.gray(
            `    matched: ${formatMatchedFields(match.matchedFields)}`,
          ),
        );
      }
    } else if (full) {
      formatFullModeContext(task, index);
    } else {
      // Show context line: first line of description (if present)
      const context = getFirstLine(task.description);
      if (context) {
        console.log(chalk.gray(`    ${context}`));
      }
    }
  }

  console.log(summaries.taskCount(tasks.length));
}

/**
 * Format a list of tasks
 */
export function formatTaskList(
  tasks: Task[],
  verbose = false,
  index?: ReferenceIndex,
  grepPattern?: string,
  full = false,
): void {
  if (tasks.length === 0) {
    console.log(summaries.noTasks);
    return;
  }

  for (const task of tasks) {
    console.log(formatTask(task, verbose, index, full));

    // Show matched fields if grep pattern provided
    if (grepPattern) {
      const match = grepItem(
        task as unknown as Record<string, unknown>,
        grepPattern,
      );
      if (match && match.matchedFields.length > 0) {
        console.log(
          chalk.gray(
            `    matched: ${formatMatchedFields(match.matchedFields)}`,
          ),
        );
      }
    } else if (full) {
      // AC: @task-list-verbose ac-1 - Full mode shows richer context
      formatFullModeContext(task, index);
    } else {
      // Show context line: first line of description (if present)
      const context = getFirstLine(task.description);
      if (context) {
        console.log(chalk.gray(`    ${context}`));
      }
    }
  }

  console.log(summaries.taskCount(tasks.length));
}

export interface FormatTaskDetailsOptions {
  /** Show all notes including superseded ones (default: false) */
  showAllNotes?: boolean;
}

/**
 * Format task details
 */
export function formatTaskDetails(
  task: Task,
  index?: ReferenceIndex,
  options: FormatTaskDetailsOptions = {},
): void {
  console.log(chalk.bold(task.title));
  console.log(chalk.gray("─".repeat(40)));
  console.log(`${fieldLabels.ulid}      ${task._ulid}`);
  if (task.slugs.length > 0) {
    console.log(`${fieldLabels.slugs}     ${task.slugs.join(", ")}`);
  }
  console.log(`${fieldLabels.type}      ${task.type}`);
  console.log(
    `${fieldLabels.status}    ${statusColor(task.status)(task.status)}`,
  );
  console.log(`${fieldLabels.priority}  ${task.priority}`);

  // AC: @task-automation-eligibility ac-17 - show automation status
  const automationDisplay = task.automation || "unassessed";
  const automationColor =
    task.automation === "eligible"
      ? chalk.green
      : task.automation === "needs_review"
        ? chalk.yellow
        : task.automation === "manual_only"
          ? chalk.red
          : chalk.gray;
  console.log(
    `${fieldLabels.automation} ${automationColor(automationDisplay)}`,
  );

  if (task.spec_ref) {
    console.log(`${fieldLabels.specRef}  ${task.spec_ref}`);
  }

  // AC: @plan-derive ac-6 - display plan_ref
  if (task.plan_ref) {
    console.log(`Plan ref:  ${task.plan_ref}`);
  }

  if (task.depends_on.length > 0) {
    if (index) {
      console.log(fieldLabels.depends);
      for (const ref of task.depends_on) {
        const result = index.resolve(ref);
        if (result.ok) {
          const item = result.item;
          const status =
            "status" in item && typeof item.status === "string"
              ? statusColor(item.status as TaskStatus)(`[${item.status}]`)
              : chalk.gray("[spec]");
          // Handle both spec items (with title) and meta items (with name or id)
          const itemName =
            "title" in item
              ? item.title
              : "name" in item
                ? item.name
                : "id" in item
                  ? item.id
                  : ref;
          console.log(`  ${ref} ${chalk.gray("→")} ${itemName} ${status}`);
        } else {
          console.log(`  ${ref} ${chalk.red("(unresolved)")}`);
        }
      }
    } else {
      console.log(`${fieldLabels.depends}   ${task.depends_on.join(", ")}`);
    }
  }

  if (task.blocked_by.length > 0) {
    console.log(
      chalk.red(`${fieldLabels.blocked}   ${task.blocked_by.join(", ")}`),
    );
  }

  if (task.tags.length > 0) {
    console.log(`${fieldLabels.tags}      ${task.tags.join(", ")}`);
  }

  console.log(`${fieldLabels.created}   ${task.created_at}`);
  if (task.started_at) {
    console.log(`${fieldLabels.started}   ${task.started_at}`);
  }
  if (task.completed_at) {
    console.log(`${fieldLabels.completed} ${task.completed_at}`);
  }

  // Show resolved spec information
  if (task.spec_ref && index) {
    const result = index.resolve(task.spec_ref);
    if (result.ok) {
      const spec = result.item;
      console.log(`\n${sectionHeaders.specContext}`);
      // Handle both spec items (with title) and meta items (with name)
      const specName =
        "title" in spec
          ? spec.title
          : "name" in spec
            ? spec.name
            : "id" in spec
              ? spec.id
              : task.spec_ref;
      console.log(chalk.cyan(specName));
      if ("type" in spec && spec.type) {
        console.log(chalk.gray(`${fieldLabels.type} ${spec.type}`));
      }
      // Show implementation status
      if ("status" in spec && spec.status && typeof spec.status === "object") {
        const status = spec.status as {
          maturity?: string;
          implementation?: string;
        };
        if (status.implementation) {
          const implColor =
            status.implementation === "verified"
              ? chalk.green
              : status.implementation === "implemented"
                ? chalk.cyan
                : status.implementation === "in_progress"
                  ? chalk.yellow
                  : chalk.gray;
          console.log(
            chalk.gray(fieldLabels.implementation) +
              implColor(status.implementation),
          );
        }
      }
      if ("description" in spec && spec.description) {
        console.log(chalk.gray(fieldLabels.description));
        // Indent description lines
        const desc = String(spec.description).trim();
        for (const line of desc.split("\n")) {
          console.log(chalk.gray(`  ${line}`));
        }
      }
      if (
        "acceptance_criteria" in spec &&
        Array.isArray(spec.acceptance_criteria) &&
        spec.acceptance_criteria.length > 0
      ) {
        console.log(chalk.gray(fieldLabels.acceptanceCriteria));
        for (const ac of spec.acceptance_criteria) {
          if (ac && typeof ac === "object" && "id" in ac) {
            const acObj = ac as {
              id: string;
              given?: string;
              when?: string;
              then?: string;
            };
            console.log(chalk.gray(`  [${acObj.id}]`));
            if (acObj.given)
              console.log(chalk.gray(`    Given: ${acObj.given}`));
            if (acObj.when) console.log(chalk.gray(`    When: ${acObj.when}`));
            if (acObj.then) console.log(chalk.gray(`    Then: ${acObj.then}`));
          }
        }
      }
      // Show traceability if present
      if (
        "traceability" in spec &&
        spec.traceability &&
        typeof spec.traceability === "object"
      ) {
        const trace = spec.traceability as {
          implementation?: Array<{
            path: string;
            function?: string;
            lines?: string;
          }>;
          tests?: Array<{ path: string }>;
          commits?: string[];
          issues?: string[];
        };
        const hasTrace =
          trace.implementation?.length ||
          trace.tests?.length ||
          trace.commits?.length ||
          trace.issues?.length;
        if (hasTrace) {
          console.log(chalk.gray(fieldLabels.traceability));
          if (trace.implementation?.length) {
            for (const impl of trace.implementation) {
              let loc = `  Code: ${impl.path}`;
              if (impl.function) loc += `::${impl.function}`;
              if (impl.lines) loc += `:${impl.lines}`;
              console.log(chalk.gray(loc));
            }
          }
          if (trace.tests?.length) {
            for (const test of trace.tests) {
              console.log(chalk.gray(`  Test: ${test.path}`));
            }
          }
          if (trace.commits?.length) {
            console.log(chalk.gray(`  Commits: ${trace.commits.join(", ")}`));
          }
          if (trace.issues?.length) {
            console.log(chalk.gray(`  Issues: ${trace.issues.join(", ")}`));
          }
        }
      }
    }
  }

  if (task.notes.length > 0) {
    // Filter superseded notes unless showAllNotes is true
    const notesToShow = options.showAllNotes
      ? task.notes
      : filterSupersededNotes(task.notes);
    const hiddenCount = task.notes.length - notesToShow.length;

    console.log(`\n${sectionHeaders.notes}`);
    for (const note of notesToShow) {
      const author = note.author || "unknown";
      // Mark if this note supersedes another
      const supersededLabel = note.supersedes ? chalk.gray(" (supersedes earlier note)") : "";
      console.log(chalk.gray(`[${note.created_at}] ${author}:`) + supersededLabel);
      console.log(note.content);
    }

    // Show count of hidden notes if any
    if (hiddenCount > 0) {
      console.log(chalk.gray(`\n(${hiddenCount} superseded note${hiddenCount > 1 ? "s" : ""} hidden - use --all to show)`));
    }
  }

  if (task.todos.length > 0) {
    console.log(`\n${sectionHeaders.todos}`);
    for (const todo of task.todos) {
      const check = todo.done ? chalk.green("✓") : chalk.gray("○");
      const text = todo.done ? chalk.strikethrough.gray(todo.text) : todo.text;
      console.log(`${check} [${todo.id}] ${text}`);
    }
  }
}

