    94→    item.text.length > 60 ? `${item.text.substring(0, 57)}...` : item.text;
    95→
    96→  const line = `${chalk.gray(shortId)} ${typeStr} ${displayText}`;
    97→
    98→  console.log(line);
    99→  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
   100→}
   101→
   102→/**
   103→ * Format a meta entity for search results
   104→ */
   105→function formatSearchMeta(
   106→  entity: LoadedObservation | LoadedAgent | LoadedWorkflow | LoadedConvention,
   107→  entityType: "observation" | "agent" | "workflow" | "convention",
   108→  matchedFields: string[],
   109→): void {
   110→  const shortId = entity._ulid.slice(0, 8);
   111→  const typeStr = chalk.gray(`[${entityType}]`);
   112→
   113→  let displayText = "";
   114→  if (entityType === "observation") {
   115→    const obs = entity as LoadedObservation;
   116→    displayText =
   117→      obs.content.length > 60
   118→        ? `${obs.content.substring(0, 57)}...`
   119→        : obs.content;
   120→  } else if (entityType === "agent") {
   121→    const agent = entity as LoadedAgent;
   122→    displayText = `${agent.id} - ${agent.name}`;
   123→  } else if (entityType === "workflow") {
   124→    const workflow = entity as LoadedWorkflow;
   125→    displayText = `${workflow.id}${workflow.description ? ` - ${workflow.description}` : ""}`;
   126→  } else if (entityType === "convention") {
   127→    const convention = entity as LoadedConvention;
   128→    const rulePreview = convention.rules.length > 0 ? ` - ${convention.rules[0]}` : "";
   129→    displayText = `${convention.domain}${rulePreview}`;
   130→  }
   131→
   132→  const line = `${chalk.gray(shortId)} ${typeStr} ${displayText}`;
   133→
   134→  console.log(line);
   135→  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
   136→}
   137→
   138→interface SearchResult {
   139→  type: "item" | "task" | "inbox" | "observation" | "agent" | "workflow" | "convention";
   140→  item: LoadedSpecItem | LoadedTask | LoadedInboxItem | LoadedObservation | LoadedAgent | LoadedWorkflow | LoadedConvention;
   141→  matchedFields: string[];
   142→}
   143→
   144→/**
   145→ * Register the search command
   146→ */
   147→export function registerSearchCommand(program: Command): void {
   148→  program
   149→    .command("search <pattern>")
   150→    .description("Search across items, tasks, inbox, and meta entities with regex pattern")
   151→    .option("-t, --type <type>", "Filter by item type")
   152→    .option("-s, --status <status>", "Filter by task status")
   153→    .option("--items-only", "Search only spec items")
   154→    .option("--tasks-only", "Search only tasks")
   155→    .option("--limit <n>", "Limit results", "50")
   156→    .action(async (pattern, options) => {
   157→      try {
   158→        const ctx = await initContext();
   159→        const { itemIndex, tasks, items, refIndex } = await buildIndexes(ctx);
   160→
   161→        const results: SearchResult[] = [];
   162→        const limit = parseInt(options.limit, 10) || 50;
   163→
   164→        // Search spec items
   165→        if (!options.tasksOnly) {
   166→          for (const item of items) {
   167→            // Apply type filter
   168→            if (options.type && item.type !== options.type) continue;
   169→
   170→            const match = grepItem(
   171→              item as unknown as Record<string, unknown>,
   172→              pattern,
   173→            );
   174→            if (match) {
   175→              results.push({
   176→                type: "item",
   177→                item,
   178→                matchedFields: match.matchedFields,
   179→              });
   180→            }
   181→          }
   182→        }
   183→
   184→        // Search tasks
   185→        if (!options.itemsOnly) {
   186→          for (const task of tasks) {
   187→            // Apply status filter
   188→            if (options.status && task.status !== options.status) continue;
   189→
   190→            const match = grepItem(
   191→              task as unknown as Record<string, unknown>,
   192→              pattern,
   193→            );
   194→            if (match) {
   195→              results.push({
   196→                type: "task",
   197→                item: task,
   198→                matchedFields: match.matchedFields,
   199→              });
   200→            }
   201→          }
   202→        }
   203→
   204→        // Search inbox items (AC-7)
   205→        if (!options.itemsOnly && !options.tasksOnly) {
   206→          const inboxItems = await loadInboxItems(ctx);
   207→          for (const inboxItem of inboxItems) {
   208→            const match = grepItem(
   209→              inboxItem as unknown as Record<string, unknown>,
   210→              pattern,
   211→            );
   212→            if (match) {
   213→              results.push({
   214→                type: "inbox",
   215→                item: inboxItem,
   216→                matchedFields: match.matchedFields,
   217→              });
   218→            }
   219→          }
   220→        }
   221→
   222→        // Search meta entities (AC-7)
   223→        if (!options.itemsOnly && !options.tasksOnly) {
   224→          const metaCtx = await loadMetaContext(ctx);
   225→
   226→          // Search observations
   227→          for (const observation of metaCtx.observations) {
   228→            const match = grepItem(
   229→              observation as unknown as Record<string, unknown>,
   230→              pattern,
   231→            );
   232→            if (match) {
   233→              results.push({
   234→                type: "observation",
   235→                item: observation,
   236→                matchedFields: match.matchedFields,
   237→              });
   238→            }
   239→          }
   240→
   241→          // Search agents
   242→          for (const agent of metaCtx.agents) {
   243→            const match = grepItem(
   244→              agent as unknown as Record<string, unknown>,
   245→              pattern,
   246→            );
   247→            if (match) {
   248→              results.push({
   249→                type: "agent",
   250→                item: agent,
   251→                matchedFields: match.matchedFields,
   252→              });
   253→            }
   254→          }
   255→
   256→          // Search workflows
   257→          for (const workflow of metaCtx.workflows) {
   258→            const match = grepItem(
   259→              workflow as unknown as Record<string, unknown>,
   260→              pattern,
   261→            );
   262→            if (match) {
   263→              results.push({
   264→                type: "workflow",
   265→                item: workflow,
   266→                matchedFields: match.matchedFields,
   267→              });
   268→            }
   269→          }
   270→
   271→          // Search conventions
   272→          for (const convention of metaCtx.conventions) {
   273→            const match = grepItem(
   274→              convention as unknown as Record<string, unknown>,
   275→              pattern,
   276→            );
   277→            if (match) {
   278→              results.push({
   279→                type: "convention",
   280→                item: convention,
   281→                matchedFields: match.matchedFields,
   282→              });
   283→            }
   284→          }
   285→        }
   286→
   287→        // Limit results
   288→        const limitedResults = results.slice(0, limit);
   289→
   290→        output(
   291→          {
   292→            pattern,
   293→            results: limitedResults.map((r) => {
   294→              // Get title/display text based on entity type
   295→              let title = "";
   296→              if (r.type === "item" || r.type === "task") {
   297→                title = (r.item as LoadedSpecItem | LoadedTask).title;
   298→              } else if (r.type === "inbox") {
   299→                title = (r.item as LoadedInboxItem).text;
   300→              } else if (r.type === "observation") {
   301→                title = (r.item as LoadedObservation).content;
   302→              } else if (r.type === "agent") {
   303→                const agent = r.item as LoadedAgent;
   304→                title = `${agent.id} - ${agent.name}`;
   305→              } else if (r.type === "workflow") {
   306→                const workflow = r.item as LoadedWorkflow;
   307→                title = workflow.id;
   308→              } else if (r.type === "convention") {
   309→                title = (r.item as LoadedConvention).domain;
   310→              }
   311→
   312→              return {
   313→                type: r.type,
   314→                ulid: r.item._ulid,
   315→                title,
   316→                matchedFields: r.matchedFields,
   317→              };
   318→            }),
   319→            total: results.length,
   320→            showing: limitedResults.length,
   321→          },
   322→          () => {
   323→            if (limitedResults.length === 0) {
   324→              console.log(chalk.gray(`No matches found for "${pattern}"`));
   325→              return;
   326→            }
   327→
   328→            for (const result of limitedResults) {
   329→              if (result.type === "item") {
   330→                formatSearchItem(
   331→                  result.item as LoadedSpecItem,
   332→                  result.matchedFields,
   333→                );
   334→              } else if (result.type === "task") {
   335→                formatSearchTask(
   336→                  result.item as LoadedTask,
   337→                  result.matchedFields,
   338→                );
   339→              } else if (result.type === "inbox") {
   340→                formatSearchInbox(
   341→                  result.item as LoadedInboxItem,
   342→                  result.matchedFields,
   343→                );
   344→              } else if (result.type === "observation" || result.type === "agent" || result.type === "workflow" || result.type === "convention") {
   345→                formatSearchMeta(
   346→                  result.item as LoadedObservation | LoadedAgent | LoadedWorkflow | LoadedConvention,
   347→                  result.type,
   348→                  result.matchedFields,
   349→                );
   350→              }
   351→            }
   352→
   353→            console.log(
   354→              chalk.gray(
   355→                `\n${limitedResults.length} result(s)${results.length > limit ? ` (showing first ${limit})` : ""}`,
   356→              ),
   357→            );
   358→          },
   359→        );
   360→      } catch (err) {
   361→        error(errors.failures.search, err);
   362→        process.exit(EXIT_CODES.ERROR);
   363→      }
   364→    });
   365→}
