    return;
  }

  console.log(chalk.bold("Meta-Spec Summary"));
  console.log(chalk.gray("─".repeat(40)));
  console.log(`Agents:       ${stats.agents}`);
  console.log(`Workflows:    ${stats.workflows}`);
