            } else {
              console.log(chalk.yellow("No focus set"));
            }
          });
          return;
        }

        // Set focus to ref
        sessionCtx.focus = ref.startsWith("@") ? ref : `@${ref}`;
        await saveSessionContext(ctx, sessionCtx);

        output({ focus: sessionCtx.focus }, () =>
          success(`Set focus to: ${sessionCtx.focus}`),
        );
