  for (const ref of refs) {
    const result = index.resolve(ref);
    if (!result.ok) {
      throw new Error(`Cannot resolve task reference: ${ref}`);
    }

    // Verify it's a task (not a spec item)
    const task = tasks.find((t) => t._ulid === result.ulid);
    if (!task) {
      throw new Error(`Reference ${ref} is not a task`);
    }

    ulids.push(result.ulid);
  }

  return { refs, ulids };
}

/**
 * Filter session context to only include tasks from explicit scope.
 * AC: @cli-ralph ac-21
 */
function filterByExplicitTasks(
  ctx: SessionContext,
  scope: ExplicitTaskScope,
): SessionContext {
  const ulidSet = new Set(scope.ulids.map((u) => u.slice(0, 8))); // Short ULID format

  return {
    ...ctx,
    active_tasks: ctx.active_tasks.filter((t) => ulidSet.has(t.ref)),
    pending_review_tasks: ctx.pending_review_tasks.filter((t) => ulidSet.has(t.ref)),
    ready_tasks: ctx.ready_tasks.filter((t) => ulidSet.has(t.ref)),
  };
}

