  reason?: string,
): Promise<void> {
  const markerPath = path.join(rootDir, END_LOOP_MARKER_PATH);
  const dir = path.dirname(markerPath);
  await fs.mkdir(dir, { recursive: true });
  const marker: EndLoopMarker = {
    requested: true,
    timestamp: new Date().toISOString(),
