  const dir = path.dirname(markerPath);
  await fs.mkdir(dir, { recursive: true });
  const marker: EndLoopMarker = {
    requested: true,
    timestamp: new Date().toISOString(),
    reason,
  };
  await fs.writeFile(markerPath, JSON.stringify(marker, null, 2));
