                const taskWorkResponse = await agent.client.prompt({
                  sessionId: acpSessionId!,
                  prompt: [{ type: "text", text: taskWorkPrompt }],
                });

                // Log task-work completion
                await appendEvent(specDir, {
                  session_id: sessionId,
                  type: "session.update",
                  data: {
