      const context: SubagentContext = {
        taskRef: '@task-my-feature',
        taskDetails: {},
        specWithACs: null,
        gitBranch: 'main',
      };

      const prompt = buildSubagentPrompt(context);

      expect(prompt).toContain('/pr-review @task-my-feature');
    });
  });

