    80→    console.error(`Mock ACP: Simulated failure ${callCount}/${failCount}`);
    81→    return true;
    82→  }
    83→
    84→  console.error(`Mock ACP: Success after ${failCount} failures`);
    85→  return false;
    86→}
    87→
    88→// ─── Request Handlers ────────────────────────────────────────────────────────
    89→
    90→async function handleInitialize(id, _params) {
    91→  initialized = true;
    92→  sendResponse(id, {
    93→    protocolVersion: 1,
    94→    agentCapabilities: {},
    95→    agentInfo: {
    96→      name: "mock-acp",
    97→      version: "1.0.0",
    98→    },
    99→  });
   100→}
   101→
   102→async function handleNewSession(id, params) {
   103→  if (!initialized) {
   104→    sendError(id, -32002, 'Not initialized');
   105→    return;
   106→  }
   107→
   108→  sessionId = `mock-session-${Date.now()}`;
   109→  sendResponse(id, { sessionId });
   110→}
   111→
   112→async function handlePrompt(id, params) {
   113→  if (!initialized) {
   114→    sendError(id, -32002, "Not initialized");
   115→    return;
   116→  }
   117→
   118→  if (!sessionId || params.sessionId !== sessionId) {
   119→    sendError(id, -32003, "Invalid session");
   120→    return;
   121→  }
   122→
   123→  // Optional delay
   124→  if (delayMs > 0) {
   125→    await new Promise((resolve) => setTimeout(resolve, delayMs));
   126→  }
   127→
   128→  // Check if we should fail
   129→  if (shouldFail()) {
   130→    sendError(id, -32000, "Mock failure");
   131→    return;
   132→  }
   133→
   134→  // Send streaming update notification (ACP SessionUpdate format)
   135→  // SessionUpdate is a discriminated union with sessionUpdate as the discriminator
   136→  sendNotification("session/update", {
   137→    sessionId,
   138→    update: {
   139→      sessionUpdate: "agent_message_chunk",
   140→      content: { type: "text", text: responseText },
   141→    },
   142→  });
   143→
   144→  // Complete task if configured (simulates agent completing work)
   145→  // IMPORTANT: Must complete BEFORE sending response so ralph's verifyTaskCompleted() sees the change
   146→  if (completeTask && projectDir) {
   147→    try {
   148→      // Use --force to complete from pending_review state
   149→      // Use node + cliPath for CI compatibility (kspec may not be globally installed)
   150→      const cmd = cliPath === 'kspec'
   151→        ? `kspec task complete ${completeTask} --reason "Mock automated completion" --force`
   152→        : `node ${cliPath} task complete ${completeTask} --reason "Mock automated completion" --force`;
   153→      execSync(cmd, {
   154→        cwd: projectDir,
   155→        stdio: ['ignore', 'pipe', 'pipe'],
   156→      });
   157→      console.error(`Mock ACP: Completed task ${completeTask}`);
   158→    } catch (err) {
   159→      console.error(`Mock ACP: Failed to complete task ${completeTask}: ${err.message}`);
   160→      // Don't fail the mock - task completion is best-effort
   161→    }
   162→  }
   163→
   164→  // Send completion response AFTER task is completed
   165→  sendResponse(id, { stopReason });
   166→}
   167→
   168→async function handleRequestPermission(id, params) {
   169→  if (!initialized) {
   170→    sendError(id, -32002, "Not initialized");
   171→    return;
   172→  }
   173→
   174→  // Extract options from request
   175→  const options = params.options || [];
   176→
   177→  // Auto-approve: Find an "allow" option (prefer allow_always, then allow_once)
   178→  // This matches the yolo mode behavior in the real ralph command
   179→  const allowOption =
   180→    options.find((o) => o.kind === "allow_always") ||
   181→    options.find((o) => o.kind === "allow_once");
   182→
   183→  if (allowOption) {
   184→    // Grant permission using the correct ACP response format
   185→    sendResponse(id, {
   186→      outcome: { outcome: "selected", optionId: allowOption.optionId },
   187→    });
   188→  } else {
   189→    // No allow option available - cancel the request
   190→    sendResponse(id, { outcome: { outcome: "cancelled" } });
   191→  }
   192→}
   193→
   194→// ─── Message Router ──────────────────────────────────────────────────────────
   195→
   196→async function handleMessage(line) {
   197→  try {
   198→    const msg = JSON.parse(line);
   199→
   200→    if (msg.jsonrpc !== "2.0" || !msg.method) {
   201→      sendError(msg.id || null, -32600, "Invalid Request");
   202→      return;
   203→    }
   204→
   205→    switch (msg.method) {
   206→      case "initialize":
   207→        await handleInitialize(msg.id, msg.params);
   208→        break;
   209→      case "session/new":
   210→        await handleNewSession(msg.id, msg.params);
   211→        break;
   212→      case "session/prompt":
   213→        await handlePrompt(msg.id, msg.params);
   214→        break;
   215→      case "session/request_permission":
   216→        await handleRequestPermission(msg.id, msg.params);
   217→        break;
   218→      default:
   219→        sendError(msg.id, -32601, `Method not found: ${msg.method}`);
   220→    }
   221→  } catch (err) {
   222→    sendError(null, -32700, "Parse error");
   223→  }
   224→}
   225→
   226→// ─── Main ────────────────────────────────────────────────────────────────────
   227→
   228→const rl = readline.createInterface({
   229→  input: process.stdin,
   230→  output: process.stdout,
   231→  terminal: false,
   232→});
   233→
   234→rl.on('line', (line) => {
   235→  if (line.trim()) {
   236→    handleMessage(line).catch((err) => {
   237→      console.error('Mock ACP error:', err.message);
   238→    });
   239→  }
   240→});
   241→
   242→rl.on('close', () => {
   243→  process.exit(0);
   244→});
